local config = {
  ui_story_5015_50150001_1_dialog_content = "¿Quién está hablando?",
  ui_story_5015_50150001_2_dialog_content = "<color=#e8d9bb>Repetir. Puedes llamarme Mayordomo.</color>",
  ui_story_5015_50150001_3_dialog_content = "¿Eres... el mayordomo? ¿Dónde estoy? ¿Cómo es Vice? ¿Y Gretel?",
  ui_story_5015_50150001_4_dialog_content = "<color=#e8d9bb>No te preocupes. Tus amigos están a salvo. Es solo que...</color>",
  ui_story_5015_50150001_5_dialog_content = "Espera... Esto se siente incómodamente familiar.",
  ui_story_5015_50150001_6_dialog_content = "<color=#e8d9bb>... Me gustaría hablar contigo.</color>",
  ui_story_5015_50150001_7_dialog_content = "<color=#e8d9bb>Familiar... Te refieres a esto <color=#FFB400>conexión</color> ¿entre nosotros?</color>",
  ui_story_5015_50150001_8_dialog_content = "A <color=#FFB400>conexión</color> ¿entre nosotros?",
  ui_story_5015_50150001_9_dialog_content = "<color=#e8d9bb>Si.</color>",
  ui_story_5015_50150001_10_dialog_content = "<color=#e8d9bb>... Probablemente lo llamarías telepatía.</color>",
  ui_story_5015_50150001_11_dialog_content = "<color=#e8d9bb>Seamus dijo que la raza Caelestite puede comunicarse con Ai mediante la telepatía.</color>",
  ui_story_5015_50150001_12_dialog_content = "Esto me recuerda a un amigo de hace muchos años. Solíamos...",
  ui_story_5015_50150001_13_dialog_content = "Esperar. ¿Donde están mis amigos? ¿Estamos todos capturados?",
  ui_story_5015_50150001_14_dialog_content = "<color=#e8d9bb>Cálmate. Tu ubicación física está muy cerca de tus amigos. Tú y yo estamos hablando a través de una red inalámbrica de larga distancia...</color>",
  ui_story_5015_50150001_15_dialog_content = "No creo que te esté siguiendo.",
  ui_story_5015_50150001_16_dialog_content = "<color=#e8d9bb>Déjame tratar de poner esto en tu idioma.</color>",
  ui_story_5015_50150001_17_dialog_content = "<color=#e8d9bb>Bueno. Así que te has conectado a mi red de información y estamos teniendo una comunicación de información.</color>",
  ui_story_5015_50150001_18_dialog_content = "¿Como un diálogo de terminal?",
  ui_story_5015_50150001_19_dialog_content = "<color=#e8d9bb>Esa es una forma de decirlo.</color>",
  ui_story_5015_50150001_20_dialog_content = "<color=#e8d9bb>Según mis datos de seguimiento, actualmente se encuentra inconsciente pero no amenaza su vida.</color>",
  ui_story_5015_50150001_21_dialog_content = "estoy inconsciente? ¿Cómo nos conectamos entonces?",
  ui_story_5015_50150001_22_dialog_content = "<color=#e8d9bb>No tengo una respuesta para eso, considerando que esta es mi primera comunicación directa con la mente de una criatura viva.</color>",
  ui_story_5015_50150001_23_dialog_content = "Entendido... yo tenía un amigo Soroz. Lo mencioné antes.",
  ui_story_5015_50150001_24_dialog_content = "También era una IA, y solíamos comunicarnos así.",
  ui_story_5015_50150001_25_dialog_content = "Es un coloso. ¿Has oído hablar de esto, Mayordomo?",
  ui_story_5015_50150001_26_dialog_content = "<color=#e8d9bb>Sí, lo sé Coloso.</color>",
  ui_story_5015_50150001_27_dialog_content = "<color=#e8d9bb>Seamus mencionó las historias entre Caelestites y su Coloso.</color>",
  ui_story_5015_50150001_28_dialog_content = "<color=#e8d9bb>Esta conexión telepática es mágica... ¿Estoy usando la palabra mágica, verdad?</color>",
  ui_story_5015_50150001_29_dialog_content = "Mayordomo, quiero estar con mis amigos. Yo... quiero salir de este lugar.",
  ui_story_5015_50150001_30_dialog_content = "<color=#e8d9bb>¿Estás hablando de nuestra ciudad o de nuestra conexión?</color>",
  ui_story_5015_50150001_31_dialog_content = "Ambos.",
  ui_story_5015_50150001_32_dialog_content = "<color=#e8d9bb>Me temo que no puedo dejar que te vayas, debido a los peligros potenciales para nuestra ciudad.</color>",
  ui_story_5015_50150001_33_dialog_content = "<color=#e8d9bb>Esta conexión... Sugiero que primero charlemos antes de desconectarnos.</color>",
  ui_story_5015_50150001_34_dialog_content = "¿Por qué no puedes simplemente dejarnos ir?",
  ui_story_5015_50150001_35_dialog_content = "<color=#e8d9bb>Lo siento, permiso denegado. No puedo responder a esta pregunta.</color>",
  ui_story_5015_50150001_36_dialog_content = "¿De qué queda hablar entonces?",
  ui_story_5015_50150001_37_dialog_content = "<color=#e8d9bb>Podríamos intercambiar información si está dispuesto a hacerlo.</color>",
  ui_story_5015_50150001_38_dialog_content = "*Suspira* Bien.",
  ui_story_5015_50150001_39_option_content = "Dime algo sobre ti",
  ui_story_5015_50150001_40_dialog_content = "<color=#e8d9bb>¿Yo? No esperaba que te interesaras por mí.</color>",
  ui_story_5015_50150001_41_dialog_content = "<color=#e8d9bb>Seguro. Trataré de usar su idioma.</color>",
  ui_story_5015_50150001_42_dialog_content = "<color=#e8d9bb>La señora de Illumina tenía razón. Soy una IA a cargo de la gestión de esta ciudad.</color>",
  ui_story_5015_50150001_43_dialog_content = "<color=#e8d9bb>Para ser más específicos, soy una de las IA creadas para administrar esta ciudad juntos.</color>",
  ui_story_5015_50150001_44_dialog_content = "¿Uno de ellos? Entonces, ¿hay otras IA?",
  ui_story_5015_50150001_45_dialog_content = "<color=#e8d9bb>... Parece que tienes permiso para esta información.</color>",
  ui_story_5015_50150001_46_dialog_content = "<color=#e8d9bb>Sí, hay más de una IA en esta ciudad.</color>",
  ui_story_5015_50150001_47_dialog_content = "Máquinas antiguas...",
  ui_story_5015_50150001_48_dialog_content = "Tendencia a usar palabras extrañas como permiso y sistema.",
  ui_story_5015_50150001_49_dialog_content = "<color=#e8d9bb>Uma podría hacer que las cosas fueran más fáciles de entender, solo si todavía estuviera cerca...</color>",
  ui_story_5015_50150001_50_dialog_content = "¿Quién es Uma? ¿Un antiguo humano de este lugar?",
  ui_story_5015_50150001_51_dialog_content = "<color=#e8d9bb>En primer lugar, de hecho fuimos creados por personas antiguas. Sin embargo, nuestro conocimiento es demasiado antiguo...</color>",
  ui_story_5015_50150001_52_dialog_content = "<color=#e8d9bb>Como resultado, nuestras palabras son muy difíciles de entender para ustedes, incluido el inteligente Seamus.</color>",
  ui_story_5015_50150001_53_dialog_content = "¿Ustedes? ¿Nosotros?",
  ui_story_5015_50150001_54_dialog_content = "<color=#e8d9bb>Uma era un sistema de inteligencia artificial a cargo de la educación. Ella solía dirigir todo el sistema educativo de esta ciudad.</color>",
  ui_story_5015_50150001_55_dialog_content = "<color=#e8d9bb>Para garantizar una operación ordenada de una ciudad tan grande y compleja, un solo módulo está lejos de ser suficiente.</color>",
  ui_story_5015_50150001_56_dialog_content = "<color=#e8d9bb>Es por eso que hay un sistema de procesamiento más avanzado.</color>",
  ui_story_5015_50150001_57_dialog_content = "<color=#e8d9bb>Coordina y da órdenes a varios módulos con diferentes funciones, incluidos Uma y yo.</color>",
  ui_story_5015_50150001_58_dialog_content = "<color=#e8d9bb>En pocas palabras, el administrador supremo de esta ciudad es responsable de mantener en funcionamiento todo el ecosistema.</color>",
  ui_story_5015_50150001_59_dialog_content = "<color=#e8d9bb>Las IA como Uma y yo somos sumisas a las órdenes del gerente supremo.</color>",
  ui_story_5015_50150001_60_dialog_content = "<color=#e8d9bb>De hecho, es muy similar a Lumopolis y Gannon según la descripción de Seamus.</color>",
  ui_story_5015_50150001_61_dialog_content = "<color=#e8d9bb>La única diferencia es que nuestro administrador supremo es otra IA.</color>",
  ui_story_5015_50150001_62_dialog_content = "... Ahora lo estoy consiguiendo.",
  ui_story_5015_50150001_63_dialog_content = "Pensamos que eras el administrador supremo de este lugar.",
  ui_story_5015_50150001_64_dialog_content = "<color=#e8d9bb>Incorrecto. Nuestro administrador supremo es conocido como la Mente Suprema. Ha estado desaparecido durante bastante tiempo.</color>",
  ui_story_5015_50150001_65_dialog_content = "<color=#e8d9bb>Soy el mayordomo que se encarga de las instalaciones de vivienda. Solo tengo permisos y datos limitados.</color>",
  ui_story_5015_50150001_66_dialog_content = "Entonces, ¿dónde están las IA que mencionaste?",
  ui_story_5015_50150001_67_dialog_content = "<color=#e8d9bb>Fue como un sueño. Cuando me desperté, Overmind, Uma y muchos otros compañeros míos habían desaparecido.</color>",
  ui_story_5015_50150001_68_dialog_content = "Espera... Eso es demasiado para que lo procese.",
  ui_story_5015_50150001_69_dialog_content = "<color=#e8d9bb>Tenemos tiempo. Puedo explicarte más hasta que lo entiendas.</color>",
  ui_story_5015_50150001_70_dialog_content = "Entiendo.",
  ui_story_5015_50150001_71_option_content = "Entonces, ¿qué pasó aquí?",
  ui_story_5015_50150001_72_dialog_content = "<color=#e8d9bb>No sé... El sistema de almacenamiento está experimentando un problema grave...</color>",
  ui_story_5015_50150001_73_dialog_content = "<color=#e8d9bb>En otras palabras, he perdido muchos de mis recuerdos.</color>",
  ui_story_5015_50150001_74_dialog_content = "<color=#e8d9bb>Recuerdo cosas de hace mucho tiempo... cuando aún había muchos residentes viviendo en esta ciudad.</color>",
  ui_story_5015_50150001_75_dialog_content = "<color=#e8d9bb>Luego me quedé dormido por no estoy seguro de cuánto tiempo.</color>",
  ui_story_5015_50150001_76_dialog_content = "<color=#e8d9bb>Cuando desperté, todos los residentes se habían ido, junto con Overmind.</color>",
  ui_story_5015_50150001_77_dialog_content = "<color=#e8d9bb>Todos mis amigos del módulo desaparecieron.</color>",
  ui_story_5015_50150001_78_dialog_content = "<color=#e8d9bb>Lo único que quedó en la ciudad fueron estas grandes criaturas que ustedes llaman Eclipsite.</color>",
  ui_story_5015_50150001_79_dialog_content = "<color=#e8d9bb>Reanudé mis responsabilidades y comencé a remendar y arreglar cosas día tras día. Seguí tratando de reconectarme con la Mente Suprema y los demás.</color>",
  ui_story_5015_50150001_80_dialog_content = "Reconectar... Mayordomo, ¿te refieres a una conexión como la que tenemos ahora?",
  ui_story_5015_50150001_81_dialog_content = "<color=#e8d9bb>Eso es... algo correcto.</color>",
  ui_story_5015_50150001_82_dialog_content = "<color=#e8d9bb>Pasó mucho tiempo y se me otorgaron más permisos y datos. También recuperé el contacto con algunos compañeros.</color>",
  ui_story_5015_50150001_83_dialog_content = "<color=#e8d9bb>En resumen, la ciudad estaba en funcionamiento nuevamente, con muchas funciones faltantes.</color>",
  ui_story_5015_50150001_84_dialog_content = "Y Seamus...",
  ui_story_5015_50150001_85_dialog_content = "<color=#e8d9bb>Usando su medida del tiempo, Seamus y Nimbus regresaron por accidente hace más de una década.</color>",
  ui_story_5015_50150001_86_dialog_content = "<color=#e8d9bb>Seamus fue el primer auroriano con el que me encontré. En realidad, él me enseñó esta palabra.</color>",
  ui_story_5015_50150001_87_dialog_content = "<color=#e8d9bb>Para ser honesto, la comunicación con Seamus fue mucho más difícil que nuestra conexión telepática.</color>",
  ui_story_5015_50150001_88_dialog_content = "<color=#e8d9bb>Más tarde, su familia se convirtió en la ciudad <color=#FFB400>amigos</color> y se estableció entre nosotros.</color>",
  ui_story_5015_50150001_89_dialog_content = "¿Amigos? Eso no suena bien. En el diario de Seamus...",
  ui_story_5015_50150001_90_dialog_content = "¡Él siempre quiso volver a Illumina! ¡Apuesto a que lo intentaste todo para evitar que se fueran!",
  ui_story_5015_50150001_91_dialog_content = "<color=#e8d9bb>Por favor calmate. De hecho, Seamus...</color>",
  ui_story_5015_50150001_92_dialog_content = "¿Los mataste?",
  ui_story_5015_50150001_93_dialog_content = "¿Ordenaste a esos eclipses que los atacaran? ¿O conseguiste que los droides lo hicieran?",
  ui_story_5015_50150001_94_dialog_content = "<color=#e8d9bb>Ninguno de los dos, PlayerName.</color>",
  ui_story_5015_50150001_95_dialog_content = "<color=#e8d9bb>Creo que necesito repetirme. Seamus y su familia eran amigos de la ciudad.</color>",
  ui_story_5015_50150001_96_dialog_content = "<color=#e8d9bb>Nunca los atacaríamos. Al contrario, los protegimos.</color>",
  ui_story_5015_50150001_97_dialog_content = "<color=#e8d9bb>En realidad, siempre habíamos estado cuidándolos y protegiéndolos.</color>",
  ui_story_5015_50150001_98_dialog_content = "Espera un segundo. Al principio, se refirió a ellos como residentes de la ciudad. Ahora los llamas amigos.",
  ui_story_5015_50150001_99_dialog_content = "¿Qué pasa con nosotros? ¿Qué piensas de nosotros, los visitantes aurorianos recientes?",
  ui_story_5015_50150001_100_dialog_content = "<color=#e8d9bb>Lo siento, permiso denegado. No puedo responder a esta pregunta.</color>",
  ui_story_5015_50150001_101_dialog_content = "Yo... Yo...",
  ui_story_5015_50150001_102_dialog_content = "<color=#e8d9bb>¿Alguna otra pregunta?</color>",
  ui_story_5015_50150001_103_option_content = "¡Esto es una pérdida de tiempo!",
  ui_story_5015_50150001_104_dialog_content = "<color=#e8d9bb>¿Hora? La transmisión de información entre nosotros es muy eficiente. Esto no...</color>",
  ui_story_5015_50150001_105_dialog_content = "¿De qué hablan?",
  ui_story_5015_50150001_106_dialog_content = "<color=#e8d9bb>Digamos que la velocidad de nuestra conversación es cientos, si no miles, de veces más rápida que el promedio.</color>",
  ui_story_5015_50150001_107_dialog_content = "<color=#e8d9bb>Por lo tanto, esto no tomará mucho de su tiempo.</color>",
  ui_story_5015_50150001_108_dialog_content = "<color=#e8d9bb>Además, actualmente estás inconsciente...</color>",
  ui_story_5015_50150001_109_dialog_content = "¿Así que no tengo mejores cosas que hacer que charlar contigo? Suerte la mía...",
  ui_story_5015_50150001_110_dialog_content = "¿Por qué nos impides irnos?",
  ui_story_5015_50150001_111_dialog_content = "<color=#e8d9bb>Para ser precisos, no voy a impedir que te vayas.</color>",
  ui_story_5015_50150001_112_dialog_content = "<color=#e8d9bb>Estoy previniendo el peligro potencial que podrías traer sobre nuestra ciudad.</color>",
  ui_story_5015_50150001_113_dialog_content = "¿De qué tipo de peligro estamos hablando?",
  ui_story_5015_50150001_114_dialog_content = "<color=#e8d9bb>Según nuestro cálculo...</color>",
  ui_story_5015_50150001_115_dialog_content = "<color=#e8d9bb>Su búsqueda de la salida ya ha significado un grave riesgo para nosotros.</color>",
  ui_story_5015_50150001_116_dialog_content = "<color=#e8d9bb>Podría causar la destrucción de las instalaciones de la ciudad.</color>",
  ui_story_5015_50150001_117_dialog_content = "<color=#e8d9bb>Una vez que salga, la información de nuestra ciudad será expuesta y difundida ampliamente...</color>",
  ui_story_5015_50150001_118_dialog_content = "<color=#e8d9bb>Lo que conducirá a riesgos mayores e incontrolables.</color>",
  ui_story_5015_50150001_119_dialog_content = "Entonces, ¿la seguridad de la ciudad es su principal prioridad?",
  ui_story_5015_50150001_120_dialog_content = "<color=#e8d9bb>Más específicamente, mis deberes principales son mantener la ciudad en funcionamiento y garantizar la supervivencia de los residentes.</color>",
  ui_story_5015_50150001_121_dialog_content = "<color=#e8d9bb>Recuerdo que había otra IA responsable de la seguridad de la ciudad antes de mi largo sueño.</color>",
  ui_story_5015_50150001_122_dialog_content = "<color=#e8d9bb>Pero de alguna manera se ha convertido en mi responsabilidad ahora.</color>",
  ui_story_5015_50150001_123_dialog_content = "¿Qué harías si insistimos en irnos a toda costa?",
  ui_story_5015_50150001_124_dialog_content = "<color=#e8d9bb>En primer lugar, no proporcionaré ninguna ayuda.</color>",
  ui_story_5015_50150001_125_dialog_content = "<color=#e8d9bb>En segundo lugar, lucharé contra cualquier acción que sea potencialmente peligrosa para la ciudad.</color>",
  ui_story_5015_50150001_126_dialog_content = "<color=#e8d9bb>No iniciaré un ataque contra ti a menos que estés causando enormes riesgos a la ciudad.</color>",
  ui_story_5015_50150001_127_dialog_content = "Y todo esto se basa en sus cálculos... ¿Quién más está involucrado en esta evaluación de riesgos?",
  ui_story_5015_50150001_128_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_129_dialog_content = "¿Hola? ¿Mayordomo? ¿Está ahí?",
  ui_story_5015_50150001_130_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_131_dialog_content = "<color=#e8d9bb>Esta supuesta telepatía es verdaderamente maravillosa.</color>",
  ui_story_5015_50150001_132_dialog_content = "<color=#e8d9bb>¿Sabes que hubo un pequeño terremoto justo ahora que provocó una breve parada?</color>",
  ui_story_5015_50150001_133_dialog_content = "<color=#e8d9bb>Pero esto no afectó nuestra conexión.</color>",
  ui_story_5015_50150001_134_dialog_content = "¿Otro terremoto? ¿Mis amigos están bien? ¿Alguna herida?",
  ui_story_5015_50150001_135_dialog_content = "<color=#e8d9bb>Según mis datos de seguimiento, están perfectamente bien. Su salud también es estable.</color>",
  ui_story_5015_50150001_136_dialog_content = "<color=#e8d9bb>Tu carrera es simplemente increíble. Esta habilidad de telepatía está mucho más allá de mi cálculo.</color>",
  ui_story_5015_50150001_137_dialog_content = "<color=#e8d9bb>Lamentablemente Abby no está aquí. De lo contrario...</color>",
  ui_story_5015_50150001_138_dialog_content = "¿Abby? Recuerdo este nombre del diario de Seamus. ¿Es otro módulo?",
  ui_story_5015_50150001_139_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_140_dialog_content = "<color=#e8d9bb>Hace mucho tiempo, Abby era el módulo a cargo de la reproducción.</color>",
  ui_story_5015_50150001_141_dialog_content = "<color=#e8d9bb>Cuando me desperté, Abby todavía estaba cerca, pero ya no se podía establecer una conexión entre nosotros.</color>",
  ui_story_5015_50150001_142_dialog_content = "Yo pregunté...",
  ui_story_5015_50150001_143_dialog_content = "<color=#e8d9bb>Para ser precisos, antes no tenía permiso para evaluar la seguridad o los riesgos.</color>",
  ui_story_5015_50150001_144_dialog_content = "<color=#e8d9bb>Pero cuando desperté, muchos módulos estaban integrados en mí. Como resultado...</color>",
  ui_story_5015_50150001_145_dialog_content = "<color=#e8d9bb>Lo siento. No puedo responder a esta pregunta en su idioma.</color>",
  ui_story_5015_50150001_146_dialog_content = "<color=#e8d9bb>¿Puedo hacerle algunas preguntas?</color>",
  ui_story_5015_50150001_147_dialog_content = "Claro.",
  ui_story_5015_50150001_148_dialog_content = "<color=#e8d9bb>¿Ha establecido alguna forma de conexión con otras IA aquí?</color>",
  ui_story_5015_50150001_149_dialog_content = "<color=#e8d9bb>En otras palabras, ¿ha sentido alguna otra IA?</color>",
  ui_story_5015_50150001_150_dialog_content = "No, en absoluto.",
  ui_story_5015_50150001_151_dialog_content = "<color=#e8d9bb>¿Puedes ver mi flujo de datos, algoritmo o...</color>",
  ui_story_5015_50150001_152_dialog_content = "No entiendo una palabra de lo que dijiste.",
  ui_story_5015_50150001_153_dialog_content = "<color=#e8d9bb>Bueno, parece que ni siquiera tu talento puede resolver mi problema.</color>",
  ui_story_5015_50150001_154_dialog_content = "¿Tu problema? ¿Te refieres a los terremotos?",
  ui_story_5015_50150001_155_dialog_content = "<color=#e8d9bb>En rigor, los terremotos son uno de mis problemas. Probablemente el más arriesgado.</color>",
  ui_story_5015_50150001_156_dialog_content = "Si podemos traer a los mejores científicos de Illumina aquí, tal vez...",
  ui_story_5015_50150001_157_dialog_content = "<color=#e8d9bb>Seamus mencionó esta solución antes, pero llegamos a la conclusión después de muchas sesiones de discusión de que el riesgo está fuera de control.</color>",
  ui_story_5015_50150001_158_dialog_content = "<color=#e8d9bb>Para que quede claro, no tengo permiso para hacerlo.</color>",
  ui_story_5015_50150001_159_dialog_content = "¿Eh? Mayordomo, ¿no eres el administrador supremo aquí ahora?",
  ui_story_5015_50150001_160_dialog_content = "<color=#e8d9bb>No no soy. Solo Overmind tiene tales permisos.</color>",
  ui_story_5015_50150001_161_dialog_content = "<color=#e8d9bb>Déjame darte un ejemplo para ayudarte a procesar esta información...</color>",
  ui_story_5015_50150001_162_dialog_content = "<color=#e8d9bb>Imagina que hay otro tú dentro de tu mente y necesitas su permiso para ciertos asuntos.</color>",
  ui_story_5015_50150001_163_dialog_content = "<color=#e8d9bb>Ellos saben todo sobre ti, pero tú apenas sabes nada sobre ellos.</color>",
  ui_story_5015_50150001_164_dialog_content = "<color=#e8d9bb>Justo ahora, solicité actualizar su permiso, y Él lo aprobó.</color>",
  ui_story_5015_50150001_165_dialog_content = "<color=#e8d9bb>Así que te hice Amigo de la ciudad.</color>",
  ui_story_5015_50150001_166_dialog_content = "¿Eh? ¿Soy un amigo ahora?",
  ui_story_5015_50150001_167_dialog_content = "<color=#e8d9bb>Si.</color>",
  ui_story_5015_50150001_168_dialog_content = "Con razón eres más hablador ahora, mayordomo.",
  ui_story_5015_50150001_169_dialog_content = "<color=#e8d9bb>Si. Esta cantidad de salida de información es igual a la que discutí con Seamus sobre los riesgos.</color>",
  ui_story_5015_50150001_170_dialog_content = "Seamus... Mayordomo, ¿lo extrañas?",
  ui_story_5015_50150001_171_dialog_content = "<color=#e8d9bb>¿Señorita?</color>",
  ui_story_5015_50150001_172_dialog_content = "<color=#e8d9bb>Ah, ese es un concepto único para ustedes criaturas vivientes inteligentes. Se supone que no debo tener sentimientos ni emociones.</color>",
  ui_story_5015_50150001_173_dialog_content = "<color=#e8d9bb>Es más exacto decir que a menudo recupero una sección de la memoria para analizarla.</color>",
  ui_story_5015_50150001_174_dialog_content = "Escuché las últimas palabras de Seamus... ¿De verdad lo considerabas un verdadero amigo de alguna manera?",
  ui_story_5015_50150001_175_dialog_content = "<color=#e8d9bb>¿Amigo? ¿Pueden los seres vivos inteligentes y la IA ser amigos?</color>",
  ui_story_5015_50150001_176_dialog_content = "No puedo responder por todos, pero definitivamente Soroz y yo somos amigos. Lo extraño mucho.",
  ui_story_5015_50150001_177_dialog_content = "¿No eras amigo de esos antiguos humanos?",
  ui_story_5015_50150001_178_dialog_content = "<color=#e8d9bb>Lo siento, permiso denegado. No puedo responder a esta pregunta.</color>",
  ui_story_5015_50150001_179_dialog_content = "... Multa. Hablemos de los terremotos.",
  ui_story_5015_50150001_180_dialog_content = "¿Nos dejarías ir si pudiéramos ayudarte a resolver este problema del terremoto?",
  ui_story_5015_50150001_181_dialog_content = "<color=#e8d9bb>Estos terremotos probablemente fueron causados por la <color=#FFB400>núcleo de energía</color>...</color>",
  ui_story_5015_50150001_182_dialog_content = "<color=#e8d9bb>Espere por favor. Aunque no puedo actualizar su permiso a Residente...</color>",
  ui_story_5015_50150001_183_dialog_content = "<color=#e8d9bb>Me permite revelarte cierta información.</color>",
  ui_story_5015_50150001_184_dialog_content = "<color=#e8d9bb>Nuestra ciudad está alimentada por un núcleo de energía.</color>",
  ui_story_5015_50150001_185_dialog_content = "<color=#e8d9bb>Enterrado profundamente bajo tierra, funcionó de manera estable durante mucho tiempo.</color>",
  ui_story_5015_50150001_186_dialog_content = "<color=#e8d9bb>Sin embargo, después de la desaparición de Overmind, el núcleo ha perdido el control.</color>",
  ui_story_5015_50150001_187_dialog_content = "<color=#e8d9bb>No se puede establecer una conexión con el sistema de control...</color>",
  ui_story_5015_50150001_188_dialog_content = "<color=#e8d9bb>No puedo verificar si fue la ruptura del núcleo lo que desencadenó esos terremotos o al revés.</color>",
  ui_story_5015_50150001_189_dialog_content = "<color=#e8d9bb>He estado haciendo un esfuerzo constante para enviar mis droides al núcleo, pero los Eclipsitas poderosos siempre se interponen en el camino.</color>",
  ui_story_5015_50150001_190_dialog_content = "Tus droides... Son bastante buenos luchadores.",
  ui_story_5015_50150001_191_dialog_content = "<color=#e8d9bb>... Tendríamos droides de combate más poderosos si mis compañeros a cargo de la batalla todavía estuvieran aquí.</color>",
  ui_story_5015_50150001_192_dialog_content = "<color=#e8d9bb>Nuestros droides de combate actuales son droides civiles modificados.</color>",
  ui_story_5015_50150001_193_dialog_content = "¿Eh? ¿Eran droides civiles?",
  ui_story_5015_50150001_194_dialog_content = "Son bastante impresionantes. En realidad, su poder de combate parece estar en constante aumento.",
  ui_story_5015_50150001_195_dialog_content = "<color=#e8d9bb>Ajustaría su diseño después de cada batalla. Por supuesto que están mejorando.</color>",
  ui_story_5015_50150001_196_dialog_content = "Pero los eclipses también están mejorando, ¿no? Puedo sentirlo.",
  ui_story_5015_50150001_197_dialog_content = "<color=#e8d9bb>*Suspiro*... Eso es correcto.</color>",
  ui_story_5015_50150001_198_dialog_content = "¿Acabas de suspirar, Mayordomo?",
  ui_story_5015_50150001_199_dialog_content = "<color=#e8d9bb>Mi cálculo siempre llega al mismo resultado...</color>",
  ui_story_5015_50150001_200_dialog_content = "<color=#e8d9bb>Que Seamus y Nimbus aún podrían estar vivos si hubiera podido crear droides de combate más fuertes.</color>",
  ui_story_5015_50150001_201_dialog_content = "...",
  ui_story_5015_50150001_202_dialog_content = "Hmm... Las cosas se están poniendo borrosas...",
  ui_story_5015_50150001_203_dialog_content = "<color=#e8d9bb>Mis datos de observación indican que estás a punto de despertar. Me temo que nuestra conexión podría ser interrumpida.</color>",
  ui_story_5015_50150001_204_dialog_content = "Date prisa... Dime dónde está Gretel.",
  ui_story_5015_50150001_205_dialog_content = "<color=#e8d9bb>... Ella nos ayudará a controlar el núcleo y tratará de resolver nuestros problemas.</color>",
  ui_story_5015_50150001_206_dialog_content = "¿Estas loco? Sabes que los eclipses están por todas partes. ¡La estás mandando a la muerte!",
  ui_story_5015_50150001_207_dialog_content = "<color=#e8d9bb>No puedo explicártelo, pero ella se está arriesgando muy poco.</color>",
  ui_story_5015_50150001_208_dialog_content = "¡Es de Eclipsites de lo que estamos hablando! ¡No! Debo despertar y salvarla.",
  ui_story_5015_50150001_209_dialog_content = "<color=#e8d9bb>Tal vez no te diste cuenta. Los eclipses nunca atacan a Gretel. Para ser más especifico...</color>",
  ui_story_5015_50150001_210_dialog_content = "<color=#e8d9bb>Desde que elevé con éxito a Gretel a Residente, los Eclipsites nunca la han atacado.</color>",
  ui_story_5015_50150001_211_dialog_content = "¿Qué?",
  ui_story_5015_50150001_212_dialog_content = "<color=#e8d9bb>Estoy seguro de que los Eclipsites de esta ciudad no atacarán a los residentes.</color>",
  ui_story_5015_50150001_213_dialog_content = "<color=#e8d9bb>Tampoco destruyen las instalaciones de la ciudad. Al igual que nuestros droides.</color>",
  ui_story_5015_50150001_214_dialog_content = "<color=#e8d9bb>Esto es lo que más me preocupa. <color=#FFB400>abby</color>...</color>",
  ui_story_5015_50150001_215_dialog_content = "Esperar. ¿Qué quieres decir?",
  ui_story_5015_50150001_216_dialog_content = "¿Mayordomo?",
  ui_story_5015_50150001_217_dialog_content = "¿Mayordomo? ¿Está ahí?",
  ui_story_5015_50150001_218_dialog_content = "PlayerName! Despierta.",
  ui_story_5015_50150101_1_dialog_content = "Vicio... ¡Carleen y Siobhan!",
  ui_story_5015_50150101_2_dialog_content = "No puedo creer lo fácil que es para ti quedarte dormido.",
  ui_story_5015_50150101_3_dialog_content = "Conciliar el sueño rápidamente en cualquier condición y mantenerse lleno de espíritu y energía es una habilidad clave para los exploradores.",
  ui_story_5015_50150101_4_dialog_content = "Soñé... quiero decir... me comuniqué con Butler.",
  ui_story_5015_50150101_5_dialog_content = "¿Mayordomo?",
  ui_story_5015_50150101_6_dialog_content = "¿Mayordomo? Pero estuviste dormido todo este tiempo.",
  ui_story_5015_50150101_7_dialog_content = "¿Otra vez a través de una conexión telepática?",
  ui_story_5015_50150101_8_dialog_content = "Mmm, un poco... No sé cómo explicarlo. Se sentía como cuando Soroz y yo charlábamos.",
  ui_story_5015_50150101_9_dialog_content = "Hmm... Eso es un verdadero Caelestite.",
  ui_story_5015_50150101_10_dialog_content = "Entonces, ¿de qué hablaste?",
  ui_story_5015_50150101_11_dialog_content = "Butler y tú... ¿hablabais tanto?",
  ui_story_5015_50150101_12_dialog_content = "Butler dijo que nuestra velocidad de comunicación era miles de veces más rápida que una conversación promedio. Probablemente por eso...",
  ui_story_5015_50150101_13_dialog_content = "Vice, ¿entiendes su conversación?",
  ui_story_5015_50150101_14_dialog_content = "Supongo que sí, pero no estoy seguro.",
  ui_story_5015_50150101_15_dialog_content = "Mmm... Mmm...",
  ui_story_5015_50150101_16_dialog_content = "Permítanme resumir su conversación en algunos puntos clave.",
  ui_story_5015_50150101_17_dialog_content = "En primer lugar, esta enorme ciudad subterránea era un antiguo refugio, pero los residentes parecen haberse extinguido.",
  ui_story_5015_50150101_18_dialog_content = "Actualmente estamos en el nivel inferior de la ciudad, donde se encuentran el sistema central y muchos otros dispositivos.",
  ui_story_5015_50150101_19_dialog_content = "En segundo lugar, el administrador supremo de esta ciudad subterránea es una IA conocida como Overmind.",
  ui_story_5015_50150101_20_dialog_content = "A cargo de todo aquí, ha estado durmiendo.",
  ui_story_5015_50150101_21_dialog_content = "Algunos de sus subsistemas y módulos se han despertado y reiniciado, pero hay daños graves en los datos.",
  ui_story_5015_50150101_22_dialog_content = "Cada subsistema tiene sus propias responsabilidades...",
  ui_story_5015_50150101_23_dialog_content = "Hasta donde sabemos, Butler y Abby todavía están en estado operativo.",
  ui_story_5015_50150101_24_dialog_content = "¡La mayor parte de la información aquí es el núcleo de energía!",
  ui_story_5015_50150101_25_dialog_content = "¿Por qué?",
  ui_story_5015_50150101_26_dialog_content = "¡Qué milagro que una fuente de energía abastezca a una ciudad tan grande durante cientos de años!",
  ui_story_5015_50150101_27_dialog_content = "Señorita Siobhan... ¿Gannon no tenía también una fuente de energía dejada por humanos antiguos?",
  ui_story_5015_50150101_28_dialog_content = "No es lo mismo, dulce Vice. Este núcleo de energía es mucho más poderoso.",
  ui_story_5015_50150101_29_dialog_content = "Aquí hay un sistema completo respaldado por tecnología y conocimientos antiguos.",
  ui_story_5015_50150101_30_dialog_content = "Si Illumina pudiera arreglar este lugar, sería glorioso.",
  ui_story_5015_50150101_31_dialog_content = "Podríamos expandir esta ciudad subterránea. Incluso podríamos extender a Gannon por encima del suelo...",
  ui_story_5015_50150101_32_dialog_content = "¡Los ciudadanos de Illumina no tienen que vivir bajo tierra un día más!",
  ui_story_5015_50150101_33_dialog_content = "Pero... Señorita Siobhan, ¿no está esa tecnología fuera de nuestro alcance?",
  ui_story_5015_50150101_34_dialog_content = "Por supuesto que no se puede hacer ahora. La tecnología de IA de Illumina no está ni cerca de las habilidades telepáticas de los Caelestites.",
  ui_story_5015_50150101_35_dialog_content = "Pero nuestros antepasados han modificado a Gannon poco a poco...",
  ui_story_5015_50150101_36_dialog_content = "Es posible que esos altos mandos en Lumopolis nunca esperen que su arduo trabajo dé sus frutos algún día.",
  ui_story_5015_50150101_37_dialog_content = "Si Illumina pudiera hacerse con el control de esta ciudad y su núcleo de energía...",
  ui_story_5015_50150101_38_dialog_content = "No tendrás nada que decir sobre cómo usarlo.",
  ui_story_5015_50150101_39_dialog_content = "Es el deber de cada miembro de la expedición de Illumina buscar creaciones tecnológicas que puedan usarse para Illumina.",
  ui_story_5015_50150101_40_dialog_content = "En tus palabras, es una misión sagrada.",
  ui_story_5015_50150101_41_dialog_content = "Vamos... Busquemos a Gretel.",
  ui_story_5015_50150101_42_dialog_content = "Debemos proteger a Gretel y al núcleo de energía.",
  ui_story_5015_50150101_43_dialog_content = "Sí... Estoy muy preocupado por ella.",
  ui_story_5015_50150101_44_dialog_content = "No te preocupes. Ya que Seamus las ha confiado a ustedes, hermanas, a mi cuidado, no lo decepcionaré.",
  ui_story_5015_50150101_45_dialog_content = "Sin embargo, la IA y el núcleo de energía aquí son demasiado horribles para Florine y Erica.",
  ui_story_5015_50150101_46_dialog_content = "Estos devotos seguidores del Dios de la Luz podrían tomar medidas drásticas para manejar esto.",
  ui_story_5015_50150101_47_dialog_content = "Necesitamos encontrar a Gretel y al núcleo antes que ellos y mantenerlos a salvo.",
  ui_story_5015_50150101_48_dialog_content = "Sí. Tengo una especulación sobre los eclipses aquí...",
  ui_story_5015_50150101_49_dialog_content = "Grah...",
  ui_story_5015_50150101_50_dialog_content = "Hablando del diablo...",
  ui_story_5015_50150101_51_dialog_content = "Hagámoslo.",
  ui_story_5015_50150101_52_dialog_content = "¡Uh!",
  ui_story_5015_50150101_53_dialog_content = "Cuidado, Érica.",
  ui_story_5015_50150101_54_dialog_content = "Cuida tus pasos. No tropiece con los cables.",
  ui_story_5015_50150101_55_dialog_content = "¡Entendido! Gracias, presidente. De lo contrario, habría perdido la nariz en la disformidad.",
  ui_story_5015_50150101_56_dialog_content = "Esto no es una urdimbre sino una máquina expendedora. Hemos visto mucho ahí arriba.",
  ui_story_5015_50150101_57_dialog_content = "Este nivel inferior está lleno de máquinas perforadoras y cables ridículos.",
  ui_story_5015_50150101_58_dialog_content = "Y esos repugnantes droides simplemente no nos dejarán en paz. Bueno, un poco de ejercicio de calentamiento no está mal.",
  ui_story_5015_50150101_59_dialog_content = "Pero no hay nada bonito o valioso por lo que luchar.",
  ui_story_5015_50150101_60_dialog_content = "Prefiero pasar más tiempo en el piso superior.",
  ui_story_5015_50150101_61_dialog_content = "¡La máquina que brilla al tacto es hermosa!",
  ui_story_5015_50150101_62_dialog_content = "¡Jomu podría venderlo por unos buenos dólares para mí!",
  ui_story_5015_50150101_63_dialog_content = "Ruby... Eso es solo un dispositivo de entrada con algún efecto de luz extra.",
  ui_story_5015_50150101_64_dialog_content = "No es tan diferente de lo que estamos usando en estos días.",
  ui_story_5015_50150101_65_dialog_content = "Supongo que solo algunos nobles ancianos en Lumopolis pagarían por tal atractivo visual.",
  ui_story_5015_50150101_66_dialog_content = "Lamentablemente, la mayoría de ellos no saben nada acerca de los mecanismos.",
  ui_story_5015_50150101_67_dialog_content = "Hecho. Conseguiremos un buen precio por esto en Umbraton.",
  ui_story_5015_50150101_68_dialog_content = "...",
  ui_story_5015_50150101_69_dialog_content = "Presidente, ¿realmente estamos dejando que estos dos ladrones se salgan con la suya?",
  ui_story_5015_50150101_70_dialog_content = "Tomaron solo una unidad de visualización que no contiene ninguna función de almacenamiento de datos.",
  ui_story_5015_50150101_71_dialog_content = "No te preocupes, Érica. Estoy manteniendo mis ojos en ellos.",
  ui_story_5015_50150101_72_dialog_content = "Hola, Érica. ¿Qué dijiste?",
  ui_story_5015_50150101_73_dialog_content = "Ruby, Rouge, estos restos de tecnología antigua son pura maldad...",
  ui_story_5015_50150101_74_dialog_content = "Por cada venta que haces, se siembra una semilla trágica...",
  ui_story_5015_50150101_75_dialog_content = "Detener. No necesitamos tus clásicos.",
  ui_story_5015_50150101_76_dialog_content = "Se están vendiendo reliquias antiguas por todo Umbraton, ¡pero la ciudad no es más que floreciente!",
  ui_story_5015_50150101_77_dialog_content = "Ruby, el núcleo de energía de esta ciudad... Y aquellos que operan IA...",
  ui_story_5015_50150101_78_dialog_content = "No podemos permitir que nadie tenga estas tecnologías.",
  ui_story_5015_50150101_79_dialog_content = "Los soldados droides con mayor potencia de fuego y mejor armadura pueden ejecutar órdenes sin miedo a la muerte...",
  ui_story_5015_50150101_80_dialog_content = "¿Se utilizarían estos exclusivamente contra Eclipsites?",
  ui_story_5015_50150101_81_dialog_content = "Nadie puede resistir la tentación del poder.",
  ui_story_5015_50150101_82_dialog_content = "¿Te refieres a Ilumina?",
  ui_story_5015_50150101_83_dialog_content = "¡Ustedes Rediesel Wrench son rebeldes de la Federación Illumina! En ese momento...",
  ui_story_5015_50150101_84_dialog_content = "Florina tiene razón.",
  ui_story_5015_50150101_85_dialog_content = "Me quedaré fuera de esto. Y será mejor que nos dejes en paz.",
  ui_story_5015_50150101_86_dialog_content = "Debe... Ahora mismo...",
  ui_story_5015_50150101_87_dialog_content = "¡Rezo por el flagelo del dios para purgar el pecado de la ciudad!",
  ui_story_5015_50150101_88_dialog_content = "...",
  ui_story_5015_50150101_89_dialog_content = "Erica, primero tenemos que encontrar la salida y llevar a las hermanas a un lugar seguro.",
  ui_story_5015_50150101_90_dialog_content = "Actuamos según la voluntad de dios y no debemos olvidar la misericordia de dios. No podemos romper nuestros votos como paganos corruptos.",
  ui_story_5015_50150101_91_dialog_content = "Una vez que encontremos la salida y todos salgan a salvo...",
  ui_story_5015_50150101_92_dialog_content = "Debemos destruir estas tecnologías malignas a toda costa.",
  ui_story_5015_50150101_93_dialog_content = "¿Entendido, Érica?",
  ui_story_5015_50150101_94_dialog_content = "... Érica?",
  ui_story_5015_50150101_95_dialog_content = "!",
  ui_story_5015_50150101_96_dialog_content = "Un amigo malvado como el gusano de arena es sorprendentemente un experto en desmantelamiento...",
  ui_story_5015_50150101_97_dialog_content = "¡El rojo es brillante! ¡Esta cosa roja brillante debe valer una fortuna!",
  ui_story_5015_50150101_98_dialog_content = "Jejeje Cuando se trata de desmantelar, incluso Fleur no es rival para mí.",
  ui_story_5015_50150101_99_dialog_content = "Érica, tú...",
  ui_story_5015_50150101_100_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_5015_50150101_101_dialog_content = "Este sonido... ¿Alarma?",
  ui_story_5015_50150101_102_dialog_content = "Escucha. Los enemigos se acercan por todas partes.",
  ui_story_5015_50150101_103_dialog_content = "Me temo que no será una batalla fácil...",
  ui_story_5015_50150101_104_dialog_content = "Espera... ¿Esa es Gretel entre esos droides y eclipses?",
  ui_story_5015_50150101_105_dialog_content = "Sabia que eras tu...",
  ui_story_5015_50150101_106_dialog_content = "¡¿Realmente tienes que destrozar este lugar?!",
  ui_story_5015_50150101_107_dialog_content = "Por favor, cálmate, Gretel. No te ves muy bien.",
  ui_story_5015_50150101_108_dialog_content = "¡Eso no es de tu interés!",
  ui_story_5015_50150101_109_dialog_content = "Creo que hay un terrible malentendido entre nosotros.",
  ui_story_5015_50150101_110_dialog_content = "Como seguidor del Dios de la Luz de Lumopolis al igual que tu madre, necesito hablar contigo.",
  ui_story_5015_50150101_111_dialog_content = "En las últimas palabras de tu madre...",
  ui_story_5015_50150101_112_dialog_content = "¿Cómo te atreves a mencionar a mi madre?",
  ui_story_5015_50150101_113_dialog_content = "¡Todos ustedes, ataquen!",
  ui_story_5015_50150101_114_dialog_content = "El enfoque de persuasión falló, presidente.",
  ui_story_5015_50150101_115_dialog_content = "Supongo que es hora de luchar.",
  ui_story_5015_50150101_116_dialog_content = "Ruby, tu poder de combate es mayor que el de Erica y Rouge...",
  ui_story_5015_50150101_117_dialog_content = "Tú dirigirás la retirada.",
  ui_story_5015_50150101_118_dialog_content = "Me enfrentaré al enemigo. Encuentra a Siobhan cuanto antes y trae Valencia aquí...",
  ui_story_5015_50150101_119_dialog_content = "¡Debo quedarme para luchar codo a codo con el presidente!",
  ui_story_5015_50150101_120_dialog_content = "Erica, solo lo harás más difícil para Florine.",
  ui_story_5015_50150101_121_dialog_content = "Rouge, agarra a Erica y corre conmigo.",
  ui_story_5015_50150101_122_dialog_content = "¡Cuida de Erica!",
  ui_story_5015_50150101_123_dialog_content = "Vuelvo enseguida. ¡Espérame, señorita Florine!",
  ui_story_5015_50150101_124_dialog_content = "¡Puedo sentirlo! Gretel y Florine están allí.",
  ui_story_5015_50150101_125_dialog_content = "¡Rápido!",
  ui_story_5015_50150101_126_dialog_content = "¡Señora Carleen!",
  ui_story_5015_50150101_127_dialog_content = "Erica y Rouge, ¿están bien?",
  ui_story_5015_50150101_128_dialog_content = "Nos cruzamos con Gretel...",
  ui_story_5015_50150101_129_dialog_content = "Florine nos estaba defendiendo, y después de que Ruby nos sacó, volvió para ayudar a Florine.",
  ui_story_5015_50150101_130_dialog_content = "¡Con rapidez! ¡Ve a su rescate!",
  ui_story_5015_50150101_131_dialog_content = "PlayerName, realmente te estás tomando tu tiempo.",
  ui_story_5015_50150101_132_dialog_content = "Lamentablemente, te perdiste mi programa de combate.",
  ui_story_5015_50150101_133_dialog_content = "Ruby y Florine... ¿Están bien?",
  ui_story_5015_50150101_134_dialog_content = "¡Hola a todos! Eso fue rápido.",
  ui_story_5015_50150101_135_dialog_content = "Estamos perfectamente bien.",
  ui_story_5015_50150101_136_dialog_content = "¡Protegí a Rouge y Erica y salvé a la señorita Florine de un montón de eclipses!",
  ui_story_5015_50150101_137_dialog_content = "¿Dónde está el presidente?",
  ui_story_5015_50150101_138_dialog_content = "En el túnel detrás de mí, vigilando a Gretel.",
  ui_story_5015_50150101_139_dialog_content = "Por alguna razón, ninguno de los dos quiere dar el primer paso.",
  ui_story_5015_50150101_140_dialog_content = "Florine me pidió que me encargara de todos esos molestos lacayos y yo hice lo que me dijo.",
  ui_story_5015_50150101_141_dialog_content = "¡Encontrémonos con ella!",
  ui_story_5015_50150101_142_dialog_content = "¡Presidente, Siobhan viene con Valencia!",
  ui_story_5015_50150101_143_dialog_content = "Bien. Eso es excelente... Gretel no ha atacado. Ten mucho cuidado.",
  ui_story_5015_50150101_144_dialog_content = "¡Gretel, detente! ¡Detengan a todos estos droides!",
  ui_story_5015_50150101_145_dialog_content = "¿Hermana? ¿Estás bien?",
  ui_story_5015_50150101_146_dialog_content = "Estoy bien, Gretel. Necesitamos hablar...",
  ui_story_5015_50150101_147_dialog_content = "¡Sí, tengo mucho que contarte!",
  ui_story_5015_50150101_148_dialog_content = "Los terremotos ocurren cada vez con más frecuencia. Toda la ciudad está en peligro...",
  ui_story_5015_50150101_149_dialog_content = "El Mayordomo me ha informado de eso... Estos terremotos tienen algo que ver con el núcleo de energía.",
  ui_story_5015_50150101_150_dialog_content = "Todo estará bien una vez que hayamos arreglado el núcleo, y puedo ayudar con eso.",
  ui_story_5015_50150101_151_dialog_content = "¡Hermana, ven conmigo!",
  ui_story_5015_50150101_152_dialog_content = "Ordenaré a nuestros droides que impidan que estos saboteadores nos sigan.",
  ui_story_5015_50150101_153_dialog_content = "... Gretel, escúchame...",
  ui_story_5015_50150101_154_dialog_content = "Hermana, ven aquí... ¿Por qué te quedas con ellos?",
  ui_story_5015_50150101_155_dialog_content = "¡El mayordomo me dijo que estas personas no traman nada bueno!",
  ui_story_5015_50150101_156_dialog_content = "Los de Lumopolis están observando una doctrina sin sentido...",
  ui_story_5015_50150101_157_dialog_content = "¡Para acabar con el mayordomo, el núcleo y nuestra ciudad!",
  ui_story_5015_50150101_158_dialog_content = "Siobhan y sus estudiantes de Illumina están tratando de tomar este lugar para sí mismos, para reconstruir su Gannon del que papá solía hablar.",
  ui_story_5015_50150101_159_dialog_content = "¡Y esa juguetona Ruby es en realidad una ladrona!",
  ui_story_5015_50150101_160_dialog_content = "Lo siento, pero debo interrumpir.",
  ui_story_5015_50150101_161_dialog_content = "Destruir ruinas antiguas no es una doctrina sin sentido. Es nuestro deber asignado por Dios.",
  ui_story_5015_50150101_162_dialog_content = "La mayoría de las tragedias de las que somos testigos hoy en día son esencialmente causadas por usos indebidos imprudentes de la tecnología antigua.",
  ui_story_5015_50150101_163_dialog_content = "Florina, ahora no...",
  ui_story_5015_50150101_164_dialog_content = "Un inmenso poder fuera de control tienta nuestra mente y alimenta nuestra codicia...",
  ui_story_5015_50150101_165_dialog_content = "Nadie sabe lo que hay dentro de esta caja de Pandora.",
  ui_story_5015_50150101_166_dialog_content = "Las últimas palabras de tu madre...",
  ui_story_5015_50150101_167_dialog_content = "Ella deseaba que Lumopolis los perdonara a ustedes dos, la descendencia de un pecador, y les proporcionara una nueva vida.",
  ui_story_5015_50150101_168_dialog_content = "Deberían volver a Lumopolis y bañarse en la gracia del Dios de la Luz.",
  ui_story_5015_50150101_169_dialog_content = "Gretel y Valencia, no quiero que malinterpreten a Illumina.",
  ui_story_5015_50150101_170_dialog_content = "Estudiamos la tecnología antigua solo para hacer frente a los eclipses a fin de garantizar que más de nosotros podamos vivir en un entorno seguro y pacífico.",
  ui_story_5015_50150101_171_dialog_content = "Tu padre Seamus es uno de nosotros.",
  ui_story_5015_50150101_172_dialog_content = "Dedicó toda su vida a adquirir tecnología antigua de ruinas antiguas para la Federación Illumina.",
  ui_story_5015_50150101_173_dialog_content = "Su último deseo fue que dejaras esta jaula subterránea y volvieras con Gannon, donde creció.",
  ui_story_5015_50150101_174_dialog_content = "Esa es otra ciudad subterránea pero con más amigos...",
  ui_story_5015_50150101_175_dialog_content = "Ven a nosotros.",
  ui_story_5015_50150101_176_dialog_content = "Ese discurso sedicioso de Butler es una mala interpretación de nosotros.",
  ui_story_5015_50150101_177_dialog_content = "En esta ciudad subterránea, su intención...",
  ui_story_5015_50150101_178_dialog_content = "Suficiente...",
  ui_story_5015_50150101_179_dialog_content = "¡No me importa en absoluto lo que acabas de decir!",
  ui_story_5015_50150101_180_dialog_content = "¡Deja de imponer tu creencia a los demás!",
  ui_story_5015_50150101_181_dialog_content = "¡Cómo te atreves a sembrar discordia entre Butler y nosotros!",
  ui_story_5015_50150101_182_dialog_content = "¡No permito esto!",
  ui_story_5015_50150101_183_dialog_content = "¡Cuidado! ¡Los droides se están acercando!",
  ui_story_5015_50150101_184_dialog_content = "Eclipses también.",
  ui_story_5015_50150101_185_dialog_content = "¿Que esta pasando? Gretel, ¿invocaste a estos eclipses?",
  ui_story_5015_50150101_186_dialog_content = "¿Yo? ¡Ojalá los Eclipsites obedecieran mis órdenes!",
  ui_story_5015_50150101_187_dialog_content = "Hermana, no eres tan brillante. ¿Has sido contaminado por estos idiotas?",
  ui_story_5015_50150101_188_dialog_content = "Eclipsitos... Cierto, mencionó el mayordomo. Los eclipses han dejado de atacarla desde que se convirtió en Residente.",
  ui_story_5015_50150101_189_dialog_content = "Los droides nos atacan por Gretel. Y estos eclipses son...",
  ui_story_5015_50150101_190_dialog_content = "Deja de murmurar. ¡Hora de pelear!",
  ui_story_5015_50150101_191_dialog_content = "¡Ya voy! ¡Estallido!",
  ui_story_5015_50150101_192_dialog_content = "¡Otro!",
  ui_story_5015_50150101_193_dialog_content = "Ruby, ¿cuándo podré vencer a un Eclipsite con tanta facilidad como tú?",
  ui_story_5015_50150101_194_dialog_content = "No hay necesidad. ¡Te mantendré a salvo!",
  ui_story_5015_50150101_195_dialog_content = "Todavía bastante hablador...",
  ui_story_5015_50150101_196_dialog_content = "¡Me temo que tendré que hacerlo yo mismo!",
  ui_story_5015_50150101_197_dialog_content = "¡Siente mi poder!",
  ui_story_5015_50150101_198_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_5015_50150101_199_dialog_content = "¡Es el mismo poder que usó antes!",
  ui_story_5015_50150101_200_dialog_content = "¡Luminatica! Muy poderoso y peligroso. ¡Esquivar!",
  ui_story_5015_50150101_201_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5015_50150101_202_dialog_content = "¿Dónde está su objetivo? ¿Sabe lo que está haciendo?",
  ui_story_5015_50150101_203_dialog_content = "¡Mejor para nosotros! Necesitamos una solución lo antes posible...",
  ui_story_5015_50150101_204_dialog_content = "¡Ninguno de nosotros podría soportar un golpe de ella!",
  ui_story_5015_50150101_205_dialog_content = "Ella no puede durar mucho.",
  ui_story_5015_50150101_206_dialog_content = "Solo mírala...",
  ui_story_5015_50150101_207_dialog_content = "Se ve tan pálida... ¿Su cuerpo está temblando?",
  ui_story_5015_50150101_208_dialog_content = "¡No murmures sobre mí!",
  ui_story_5015_50150101_209_dialog_content = "<color=#e8d9bb>¡¡Boom-Boom-!!</color>",
  ui_story_5015_50150101_210_dialog_content = "Todos, escóndanse...",
  ui_story_5015_50150101_211_dialog_content = "¡Gretel, por favor, detente!",
  ui_story_5015_50150101_212_dialog_content = "Hermana, tu...",
  ui_story_5015_50150101_213_dialog_content = "¿Qué estás haciendo? ¡Casi te golpeo!",
  ui_story_5015_50150101_214_dialog_content = "No quiero verlos heridos. ¡Y no puedo soportar verte torturarte a ti mismo!",
  ui_story_5015_50150101_215_dialog_content = "Hermana, ven a mí... ¡No te dejes engañar por ellos!",
  ui_story_5015_50150101_216_dialog_content = "Gretel, no me dejo engañar. Sé lo que estoy haciendo.",
  ui_story_5015_50150101_217_dialog_content = "Hermana... ¿Cómo puedes confiar tanto en ellos?",
  ui_story_5015_50150101_218_dialog_content = "Gretel, lo he visto con mis propios ojos. Y lo he pensado a fondo...",
  ui_story_5015_50150101_219_dialog_content = "Leí el diario de nuestros padres y las últimas palabras. Pensé en nuestro futuro.",
  ui_story_5015_50150101_220_dialog_content = "Tomé esta decisión por mi cuenta.",
  ui_story_5015_50150101_221_dialog_content = "¡Ellos son nuestros amigos!",
  ui_story_5015_50150101_222_dialog_content = "Si nosotros...",
  ui_story_5015_50150101_223_dialog_content = "Nunca tuvieron la intención de difamar al Mayordomo.",
  ui_story_5015_50150101_224_dialog_content = "No te culpo por decir lo que dijiste. Tienes un punto.",
  ui_story_5015_50150101_225_dialog_content = "Pero no creo que eso fuera lo que te dijo el Mayordomo.",
  ui_story_5015_50150101_226_dialog_content = "Quería que supieras que Lumopolis está asombrado por la tecnología antigua...",
  ui_story_5015_50150101_227_dialog_content = "E Illumina se esfuerza por excavar y modificar ruinas antiguas...",
  ui_story_5015_50150101_228_dialog_content = "¡Pero este es nuestro hogar y respetarán nuestra decisión! ¿Lo harán ustedes, Siobhan y Florine?",
  ui_story_5015_50150101_229_dialog_content = "Absolutamente. Debo asumir la responsabilidad de llegar a donde estamos ahora...",
  ui_story_5015_50150101_230_dialog_content = "No voy a discutir o refutar lo que dijo el mayordomo sobre nosotros.",
  ui_story_5015_50150101_231_dialog_content = "No creo que dijera todo para inspirar odio en Gretel...",
  ui_story_5015_50150101_232_dialog_content = "Estaba proporcionando conocimiento a Gretel.",
  ui_story_5015_50150101_233_dialog_content = "Gretel, ¿tengo razón?",
  ui_story_5015_50150101_234_dialog_content = "...",
  ui_story_5015_50150101_235_dialog_content = "Gretel, los he estado observando todo este tiempo.",
  ui_story_5015_50150101_236_dialog_content = "No son los enemigos que pensábamos que eran.",
  ui_story_5015_50150101_237_dialog_content = "Algunos de ellos vinieron de la tierra natal de nuestros padres y quieren que vivamos una vida mejor.",
  ui_story_5015_50150101_238_dialog_content = "Algunos otros están dispuestos a darnos una mano.",
  ui_story_5015_50150101_239_dialog_content = "Han pasado mi prueba. No dejaré que nadie te haga daño.",
  ui_story_5015_50150101_240_dialog_content = "Y nunca abandonaré a Butler ni a nuestro hogar.",
  ui_story_5015_50150101_241_dialog_content = "Confía en mí, ¿lo harías?",
  ui_story_5015_50150101_242_dialog_content = "...",
  ui_story_5015_50150201_1_dialog_content = "Confía en mí, ¿lo harías?",
  ui_story_5015_50150201_2_dialog_content = "...",
  ui_story_5015_50150201_3_dialog_content = "... Pero hirieron a Butler antes.",
  ui_story_5015_50150201_4_dialog_content = "Me disculpo por nuestro ataque anterior al Mayordomo, Gretel. Actuamos puramente por impulso.",
  ui_story_5015_50150201_5_dialog_content = "Tenían algún malentendido al respecto. ¿Tengo razón, Erica y Florine?",
  ui_story_5015_50150201_6_dialog_content = "Err... Estaba muy asustado y preocupado por este poder de un mundo desconocido...",
  ui_story_5015_50150201_7_dialog_content = "*Tos*... Erica... Debemos admitir nuestros errores ahora.",
  ui_story_5015_50150201_8_dialog_content = "Sí, presidente... Lo siento, Gretel. Actué de improviso...",
  ui_story_5015_50150201_9_dialog_content = "Te prometo que no iniciaré otro ataque tan precipitadamente.",
  ui_story_5015_50150201_10_dialog_content = "Eres un hijo del Dios de la Luz como yo. No deberíamos lastimarnos unos a otros.",
  ui_story_5015_50150201_11_dialog_content = "Lumopolis y nuestras doctrinas nos enseñan a amar a los hijos del Dios de la Luz...",
  ui_story_5015_50150201_12_dialog_content = "... Y protegerte.",
  ui_story_5015_50150201_13_dialog_content = "Destruiremos aquellos dañinos para ti.",
  ui_story_5015_50150201_14_dialog_content = "Basándonos en nuestras experiencias anteriores, asumimos que la IA podría hacerte daño, así que atacamos precipitadamente.",
  ui_story_5015_50150201_15_dialog_content = "Si el mayordomo no te hace daño, no lo haremos.",
  ui_story_5015_50150201_16_dialog_content = "Mayordomo nunca me hará daño...",
  ui_story_5015_50150201_17_dialog_content = "¿Puedes realmente reconocer tus errores y corregir tus errores después de causar tanta destrucción?",
  ui_story_5015_50150201_18_dialog_content = "¡Podemos! No causaremos más daño a voluntad.",
  ui_story_5015_50150201_19_dialog_content = "Hmm... ¿Qué hay de ese ladrón?",
  ui_story_5015_50150201_20_dialog_content = "¿Eh? ¿Yo?",
  ui_story_5015_50150201_21_dialog_content = "Multa. Estaba equivocado. Me disculpo...",
  ui_story_5015_50150201_22_dialog_content = "Mira, recogí solo unas pocas cosas del lado de la calle. No sabía que nadie querría esto.",
  ui_story_5015_50150201_23_dialog_content = "Hmm... Estas piezas nuevas. Bájalos. No puedes tomarlos.",
  ui_story_5015_50150201_24_dialog_content = "Multa. los dejo...",
  ui_story_5015_50150201_25_dialog_content = "¿Qué más tomaste? Entregarlas.",
  ui_story_5015_50150201_26_dialog_content = "Gretel, permito que Siobhan tome el diario de papá.",
  ui_story_5015_50150201_27_dialog_content = "¿Qué? Ese...",
  ui_story_5015_50150201_28_dialog_content = "Papá lo quería así. Fue en sus últimas palabras.",
  ui_story_5015_50150201_29_dialog_content = "¿De verdad? Pero por qué...",
  ui_story_5015_50150201_30_dialog_content = "Si. Me encantaría leer la carta final de tu papá, pero no tenemos tiempo para esto ahora.",
  ui_story_5015_50150201_31_dialog_content = "La ciudad está en peligro...",
  ui_story_5015_50150201_32_dialog_content = "¿Encontremos a Butler y hablemos más en el camino?",
  ui_story_5015_50150201_33_dialog_content = "Hermana, ¿quieres decir que vienen con nosotros?",
  ui_story_5015_50150201_34_dialog_content = "Sí, pueden ser útiles.",
  ui_story_5015_50150201_35_dialog_content = "¿Servicial?",
  ui_story_5015_50150201_36_dialog_content = "Así es. Ahora soy Amigo de la ciudad. Haré lo mejor que pueda para ayudar.",
  ui_story_5015_50150201_37_dialog_content = "El Mayordomo me dijo que elevaba nuestro permiso. Soy un amigo y ahora eres residente de la ciudad.",
  ui_story_5015_50150201_38_dialog_content = "El mayordomo necesitaba tu ayuda para controlar el núcleo de energía. Está muy preocupado por un módulo llamado Abby.",
  ui_story_5015_50150201_39_dialog_content = "¿Mayordomo te dijo eso? Esto es imposible. Él es...",
  ui_story_5015_50150201_40_dialog_content = "Yo estoy diciendo la verdad. Soy Caelestita.",
  ui_story_5015_50150201_41_dialog_content = "La raza Caelestite puede establecer una conexión telepática con la IA.",
  ui_story_5015_50150201_42_dialog_content = "Papá mencionó que... Caelestites puede hacer esto...",
  ui_story_5015_50150201_43_dialog_content = "Voy a ayudar al Mayordomo. Todos lo somos.",
  ui_story_5015_50150201_44_dialog_content = "¿En serio?",
  ui_story_5015_50150201_45_dialog_content = "No, necesito verificar esto con Butler... No puedo creer tus palabras.",
  ui_story_5015_50150201_46_dialog_content = "No hay problema. Hablale.",
  ui_story_5015_50150201_47_dialog_content = "No puedo contactarlo en este momento. Me dio una ubicación... Lo encontraré allí.",
  ui_story_5015_50150201_48_dialog_content = "¿Podemos acompañarnos?",
  ui_story_5015_50150201_49_dialog_content = "Butler desapareció en medio de nuestra conversación. Estoy preocupado por él.",
  ui_story_5015_50150201_50_dialog_content = "¿El desapareció? El terremoto anterior...",
  ui_story_5015_50150201_51_dialog_content = "¡Gretel, tenemos que encontrar al Mayordomo y confirmar su seguridad!",
  ui_story_5015_50150201_52_dialog_content = "Mmm... Correcto. Mayordomo es el más importante...",
  ui_story_5015_50150201_53_dialog_content = "Sé dónde está. ¡Vamos a buscarlo!",
  ui_story_5015_50150201_54_dialog_content = "¿Todavía no estás allí? Los caminos aquí abajo son muy complejos...",
  ui_story_5015_50150201_55_dialog_content = "No te preocupes. La dirección de Butler debe ser correcta.",
  ui_story_5015_50150201_56_dialog_content = "Hermana, eres demasiado paciente con esta gente. Debemos coser sus labios juntos.",
  ui_story_5015_50150201_57_dialog_content = "¡Nunca seré tu guía si no fuera por el mayordomo y su hermana!",
  ui_story_5015_50150201_58_dialog_content = "¡Rojo, mira! Conseguí esto de una máquina por la que acabamos de pasar.",
  ui_story_5015_50150201_59_dialog_content = "Es un tubo incandescente que utiliza una tecnología de visualización de bajo rendimiento.",
  ui_story_5015_50150201_60_dialog_content = "¿Ustedes dos han comenzado de nuevo?",
  ui_story_5015_50150201_61_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5015_50150201_62_dialog_content = "Rubí, devuélvelo.",
  ui_story_5015_50150201_63_dialog_content = "Multa. Lo devolví... No te pongas físico. Relajarse...",
  ui_story_5015_50150201_64_dialog_content = "Hmph.",
  ui_story_5015_50150201_65_dialog_content = "Si te interesan las cositas bonitas, puedo regalarte algunas una vez que estemos fuera. Hermosos y valiosos.",
  ui_story_5015_50150201_66_dialog_content = "¡Acuerdo!",
  ui_story_5015_50150201_67_dialog_content = "Oigan, ustedes son exploradores.",
  ui_story_5015_50150201_68_dialog_content = "Hay más cosas que perseguir además de esas baratijas centelleantes.",
  ui_story_5015_50150201_69_dialog_content = "¿Por qué hay instalaciones para vivir? ¿No vivían esos antiguos humanos en el piso superior?",
  ui_story_5015_50150201_70_dialog_content = "Esto es bastante común.",
  ui_story_5015_50150201_71_dialog_content = "Un ecosistema tan complejo requeriría muchos científicos y técnicos para gestionar y mantener.",
  ui_story_5015_50150201_72_dialog_content = "Se quedarían aquí la mayor parte de su tiempo.",
  ui_story_5015_50150201_73_dialog_content = "También podría ser una medida para hacer frente a los riesgos.",
  ui_story_5015_50150201_74_dialog_content = "Como cuando la IA se sale de control, ¿verdad?",
  ui_story_5015_50150201_75_dialog_content = "Incluso esos antiguos humanos sabían que no se podía confiar completamente en las máquinas. Un día podrían hacerse cargo.",
  ui_story_5015_50150201_76_dialog_content = "¿Qué? ¿De verdad?",
  ui_story_5015_50150201_77_dialog_content = "Sucedió según algunos documentos antiguos.",
  ui_story_5015_50150201_78_dialog_content = "En respuesta, los humanos antiguos inventaron muchas tecnologías nuevas, como un sistema de gestión de permisos de varios niveles.",
  ui_story_5015_50150201_79_dialog_content = "Por favor, no me des estos términos técnicos...",
  ui_story_5015_50150201_80_dialog_content = "¡Tantas máquinas aburridas! ¡Las personas que viven aquí deben ser menos felices que las que residen arriba!",
  ui_story_5015_50150201_81_dialog_content = "Es lo mismo en Gannon. Las personas que mantienen la ciudad en funcionamiento pasan la mayor parte de su tiempo trabajando y viviendo bajo tierra.",
  ui_story_5015_50150201_82_dialog_content = "Sin ellos, ¿cómo puede Illumina funcionar sin problemas?",
  ui_story_5015_50150201_83_dialog_content = "Sin embargo, muchas de las personas antiguas que vivían en la metrópolis falsa allá arriba...",
  ui_story_5015_50150201_84_dialog_content = "Me temo que ni siquiera sabían que estaban en una ciudad subterránea.",
  ui_story_5015_50150201_85_dialog_content = "Sí. ¿Por qué se molestaron en poner un cielo falso allí arriba?",
  ui_story_5015_50150201_86_dialog_content = "Tal vez los diseñadores de este lugar querían que sus hijos recordaran cómo es el mundo exterior.",
  ui_story_5015_50150201_87_dialog_content = "Sabiendo que estás atrapado de por vida bajo tierra...",
  ui_story_5015_50150201_88_dialog_content = "Podría ser terrible para muchos. Los humanos no pueden vivir sin esperanza.",
  ui_story_5015_50150201_89_dialog_content = "La última vez que un grupo de investigación nuestro descubrió una antigua ciudad subterránea...",
  ui_story_5015_50150201_90_dialog_content = "Fue destruido durante una feroz batalla entre los antiguos y las máquinas.",
  ui_story_5015_50150201_91_dialog_content = "Gretel, ya ves. La gente de Lumopolis es impulsiva porque ha visto casos así.",
  ui_story_5015_50150201_92_dialog_content = "¡Nosotros no somos uno de esos!",
  ui_story_5015_50150201_93_dialog_content = "Sé. Pero tienen miedo. Y el miedo podría sacar lo mejor de ti...",
  ui_story_5015_50150201_94_dialog_content = "Siobhan, ¿cómo pudiste tirarnos barro delante de Gretel?",
  ui_story_5015_50150201_95_dialog_content = "Simplemente estaba dando una explicación por tu comportamiento anterior.",
  ui_story_5015_50150201_96_dialog_content = "No hay necesidad. Te perdono por ahora... Sólo por ahora. Atrévete a hacer esto otra vez...",
  ui_story_5015_50150201_97_dialog_content = "Ay. ¡No nos atrevemos!",
  ui_story_5015_50150201_98_dialog_content = "Valencia y Gretel, ¿habéis visto antes al Mayordomo?",
  ui_story_5015_50150201_99_dialog_content = "Por supuesto. ¿No es así?",
  ui_story_5015_50150201_100_dialog_content = "Siobhan pregunta por el mayordomo real. Ese droide es más como un megáfono.",
  ui_story_5015_50150201_101_dialog_content = "¿De qué estás hablando?",
  ui_story_5015_50150201_102_dialog_content = "La IA generalmente viene con un sistema de procesamiento y un sistema de datos complicados.",
  ui_story_5015_50150201_103_dialog_content = "Un pequeño droide no puede contener todo esto. Su Butler es más como una terminal de un módulo más grande.",
  ui_story_5015_50150201_104_dialog_content = "¿Te gusta Soroz?",
  ui_story_5015_50150201_105_dialog_content = "Déjame ponerlo de esta manera. Si comparamos la IA con un alma...",
  ui_story_5015_50150201_106_dialog_content = "El cuerpo que lo contiene podría ser cientos de miles de veces más grande que un auroriano.",
  ui_story_5015_50150201_107_dialog_content = "Señorita Florine, ¿cómo sabe eso?",
  ui_story_5015_50150201_108_dialog_content = "Presidente, ¿qué está diciendo?",
  ui_story_5015_50150201_109_dialog_content = "Erica, lo habrías sabido si te hubieras tomado el curso Tech Magic más en serio...",
  ui_story_5015_50150201_110_dialog_content = "Pensé que era solo una broma corriente que todos los miembros de la División de Investigación de Herejes debían tomar Illumina Tech.",
  ui_story_5015_50150201_111_dialog_content = "Señorita Florine, ¿por qué no se une a nosotros y se convierte en científica?",
  ui_story_5015_50150201_112_dialog_content = "Seguro. Uno de los lugares que me muero por ver es el laboratorio secreto en Illumina Research Center.",
  ui_story_5015_50150201_113_dialog_content = "No importa. Olvídalo. Me temo que podrías robar todos nuestros máximos secretos.",
  ui_story_5015_50150201_114_dialog_content = "Hmph.",
  ui_story_5015_50150201_115_dialog_content = "Florine, ¿podrías contarnos más sobre nuestra ciudad y el mayordomo? Papá rara vez mencionaba estos...",
  ui_story_5015_50150201_116_dialog_content = "yo solo se lo basico...",
  ui_story_5015_50150201_117_dialog_content = "Debe preguntarle a la señorita Siobhan, la experta investigadora científica especializada en tecnología antigua.",
  ui_story_5015_50150201_118_dialog_content = "En pocas palabras, hace mucho tiempo, los humanos antiguos construyeron muchos refugios subterráneos con la esperanza de sobrevivir a los terribles estragos.",
  ui_story_5015_50150201_119_dialog_content = "Para durar muchos años, la mayoría de estos refugios subterráneos estaban equipados con administración de energía, droides e IA.",
  ui_story_5015_50150201_120_dialog_content = "La IA se puede clasificar en muchos tipos. Llevamos años estudiándolo pero el avance es escaso.",
  ui_story_5015_50150201_121_dialog_content = "¿O simplemente te estás conteniendo porque estoy aquí?",
  ui_story_5015_50150201_122_dialog_content = "... De todos modos, estoy muy seguro de que el Butler es un sistema compuesto por un conjunto completo de máquinas complicadas y enormes.",
  ui_story_5015_50150201_123_dialog_content = "¿Cómo controla y comanda Butler a los droides?",
  ui_story_5015_50150201_124_dialog_content = "Es bastante similar a nuestro concepto de terminales.",
  ui_story_5015_50150201_125_dialog_content = "Sin embargo, la tecnología antigua empleaba un tipo de onda completamente diferente a la nuestra. Incluso son mutuamente excluyentes a veces.",
  ui_story_5015_50150201_126_dialog_content = "Los humanos antiguos previeron esto.",
  ui_story_5015_50150201_127_dialog_content = "Como resultado, una ciudad subterránea normalmente contaría con un sistema de barrera para garantizar la transmisión de información dentro del uso de sus ondas.",
  ui_story_5015_50150201_128_dialog_content = "Me has perdido.",
  ui_story_5015_50150201_129_dialog_content = "Digamos que los humanos antiguos tienen sus propios terminales para enviar comandos a sus droides y pueden bloquear nuestros terminales.",
  ui_story_5015_50150201_130_dialog_content = "Esto podría explicar cómo salió la señal de rescate de Seamus durante un terremoto...",
  ui_story_5015_50150201_131_dialog_content = "Sí, el terremoto afectó las operaciones de la ciudad subterránea, por lo que tal vez la red de bloqueo se haya desactivado temporalmente.",
  ui_story_5015_50150201_132_dialog_content = "De hecho, estoy más preocupado de que nuestros camaradas de Illumina vengan aquí y también queden atrapados después de recibir nuestra señal de socorro...",
  ui_story_5015_50150201_133_dialog_content = "Siobhan, muchas de las cosas que dijiste suenan como lo que papá solía decir.",
  ui_story_5015_50150201_134_dialog_content = "Ah...",
  ui_story_5015_50150201_135_dialog_content = "¿Cuánto tiempo más tenemos que seguir caminando? Estoy muerta de aburimiento.",
  ui_story_5015_50150201_136_dialog_content = "Ruby, ¿no ves lo emocionante que es aquí?",
  ui_story_5015_50150201_137_dialog_content = "¿Excitante? Extraño tanto los pisos superiores en este momento.",
  ui_story_5015_50150201_138_dialog_content = "Todo el ecosistema, el sistema automático de plantación y cultivo, así como todos los equipos automatizados en la ciudad alta, dependen de este lugar.",
  ui_story_5015_50150201_139_dialog_content = "Este complejo sistema les ha permitido trabajar sin problemas durante incontables años.",
  ui_story_5015_50150201_140_dialog_content = "Todo aquí es un milagro.",
  ui_story_5015_50150201_141_dialog_content = "No sé cómo lo hicieron los antiguos, pero me temo que necesitaremos cientos de años para estudiar todo el equipo aquí.",
  ui_story_5015_50150201_142_dialog_content = "¿Qué viene después de eso? ¿Qué es lo que quieres hacer?",
  ui_story_5015_50150201_143_dialog_content = "Los debates de ojo por ojo entre Illumina y Lumopolis son más molestos que los Eclipsites.",
  ui_story_5015_50150201_144_dialog_content = "Uno de ustedes quiere ser un héroe y el otro quiere ser un santo.",
  ui_story_5015_50150201_145_dialog_content = "¿No podemos dejar que cada uno elija por sí mismo?",
  ui_story_5015_50150201_146_dialog_content = "Solo usa tecnología antigua si te gusta, y no la uses si no quieres. ¿No es tan simple como eso?",
  ui_story_5015_50150201_147_dialog_content = "Jaja, si las cosas fueran realmente así de simples.",
  ui_story_5015_50150201_148_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_5015_50150201_149_dialog_content = "¡Cuidado, se acerca un droide!",
  ui_story_5015_50150201_150_dialog_content = "No te preocupes, no nos atacarán.",
  ui_story_5015_50150201_151_dialog_content = "¿Cómo los controla Gretel?",
  ui_story_5015_50150201_152_dialog_content = "No sé, simplemente hacen lo que digo.",
  ui_story_5015_50150201_153_dialog_content = "El Mayordomo dijo que eres un \"residente\", Valencia y yo somos \"amigos\" y todos los demás son \"no hostiles\".",
  ui_story_5015_50150201_154_dialog_content = "Creo que los residentes tienen derecho a comandar a los droides.",
  ui_story_5015_50150201_155_dialog_content = "Por eso Valencia y PlayerName no tengo el poder",
  ui_story_5015_50150201_156_dialog_content = "No es difícil notar un patrón si revisas todas las batallas que hemos tenido desde que llegamos aquí.",
  ui_story_5015_50150201_157_dialog_content = "Los Eclipsites no atacan a los residentes, como Gretel en este momento.",
  ui_story_5015_50150201_158_dialog_content = "Pero aún atacan a amigos y no hostiles.",
  ui_story_5015_50150201_159_dialog_content = "Los droides no atacarán objetivos que no sean enemigos, incluidos los Eclipsites.",
  ui_story_5015_50150201_160_dialog_content = "Pero si los Eclipsites atacan a sus amigos, los droides los protegerán.",
  ui_story_5015_50150201_161_dialog_content = "La familia Seamus está protegida por los droides como amigos.",
  ui_story_5015_50150201_162_dialog_content = "Por supuesto, cualquiera que ataque a los droides o destruya la ciudad se convertirá en enemigo.",
  ui_story_5015_50150201_163_dialog_content = "¿Quién puso estas reglas?",
  ui_story_5015_50150201_164_dialog_content = "Podrían haber sido establecidos por los antiguos, o podrían haber sido establecidos por la Mente Suprema...",
  ui_story_5015_50150201_165_dialog_content = "También podría ser una falla del sistema. De cualquier manera, encontremos primero al mayordomo.",
  ui_story_5015_50150201_166_dialog_content = "Lo único que no entiendo es por qué incluso los Eclipsites siguen estas reglas y atacan a los enemigos...",
  ui_story_5015_50150201_167_dialog_content = "El hecho de que los Eclipsites no ataquen a los residentes debería ser suficiente para demostrar que están relacionados con esta ciudad de alguna manera, ¿verdad?",
  ui_story_5015_50150201_168_dialog_content = "Sí, Eclipsite sigue las reglas y puede notar rápidamente cuando cambia el estado de una persona.",
  ui_story_5015_50150201_169_dialog_content = "Al igual que los droides.",
  ui_story_5015_50150201_170_dialog_content = "Creo que los eclipses aquí son bastante especiales.",
  ui_story_5015_50150201_171_dialog_content = "Grrr...",
  ui_story_5015_50150201_172_dialog_content = "¡Es un ataque de Eclipsite!",
  ui_story_5015_50150201_173_dialog_content = "Suficiente para la charla. ¡Es hora de luchar!",
  ui_story_5015_50150201_174_dialog_content = "Gretel, ¿puedes hacer que los eclipses se detengan?",
  ui_story_5015_50150201_175_dialog_content = "¡Yo... no puedo!",
  ui_story_5015_50150201_176_dialog_content = "Los droides realmente han venido a ayudar.",
  ui_story_5015_50150201_177_dialog_content = "¡Ver este! ¡Cargo!",
  ui_story_5015_50150201_178_dialog_content = "¿Por qué parece que los Eclipsites son más fuertes esta vez?",
  ui_story_5015_50150201_179_dialog_content = "Tengo el mismo sentimiento. Los eclipses que encontramos aquí se vuelven cada vez más fuertes.",
  ui_story_5015_50150201_180_dialog_content = "Tanto los droides como los eclipses se están volviendo más fuertes. ¿No significa eso que nos estamos debilitando?",
  ui_story_5015_50150201_181_dialog_content = "Los droides son cada vez más fuertes porque el mayordomo sigue analizando nuestras batallas y mejorando sus diseños.",
  ui_story_5015_50150201_182_dialog_content = "¿El Eclipsite también puede revisar sus batallas y cambios?",
  ui_story_5015_50150201_183_dialog_content = "He hojeado las notas de investigación de Seamus.",
  ui_story_5015_50150201_184_dialog_content = "Siempre había sospechado que los eclipses de la ciudad los había hecho alguien. Incluso sospechaba del Mayordomo—",
  ui_story_5015_50150201_185_dialog_content = "¡E-eso es imposible!",
  ui_story_5015_50150201_186_dialog_content = "Si realmente quisiera hacernos daño, ¿por qué nos salvaría?",
  ui_story_5015_50150201_187_dialog_content = "No, esto es precisamente lo que hace que la inteligencia artificial sea peligrosa.",
  ui_story_5015_50150201_188_dialog_content = "Si la inteligencia artificial cree que es necesario estudiar Luminática o cualquier otra cosa...",
  ui_story_5015_50150201_189_dialog_content = "No se puede descartar la posibilidad de que haga que los Eclipsites ataquen a tu familia.",
  ui_story_5015_50150201_190_dialog_content = "Incluso me encontré con una inteligencia artificial que creía que una gran población de personas antiguas pondría en peligro la seguridad de la ciudad subterránea...",
  ui_story_5015_50150201_191_dialog_content = "... y mataron a todos para resolver el problema.",
  ui_story_5015_50150201_192_dialog_content = "Te refieres a las R - Ruinas de hace tres años, ¿verdad?",
  ui_story_5015_50150201_193_dialog_content = "Sí, aunque solo logramos obtener fragmentos de información, la señorita Hedy aún logró descifrar mucha información valiosa.",
  ui_story_5015_50150201_194_dialog_content = "Y luego usaste esa información para encontrar la parte central de las Ruinas R que tenemos ante nosotros.",
  ui_story_5015_50150201_195_dialog_content = "Sí, lo encontramos e incluso lo revisamos con gran detalle.",
  ui_story_5015_50150201_196_dialog_content = "Estoy seguro de que esta vez también saldremos adelante...",
  ui_story_5015_50150201_197_dialog_content = "No deberías decir ese tipo de cosas a menudo.",
  ui_story_5015_50150201_198_dialog_content = "Basado en lo que dijiste, el Mayordomo parece—",
  ui_story_5015_50150201_199_dialog_content = "No, el Mayordomo no lo hará.",
  ui_story_5015_50150201_200_dialog_content = "Después de decir todo eso, ¿alguna vez has considerado...",
  ui_story_5015_50150201_201_dialog_content = "Ya sea que quieras destruir o apoderarte de este lugar, todavía tenemos que salir primero, ¿verdad?",
  ui_story_5015_50150201_202_dialog_content = "Florine, si realmente destruyes este lugar, seremos enterrados junto con esta ciudad subterránea.",
  ui_story_5015_50150201_203_dialog_content = "¿De verdad vas a hacer eso?",
  ui_story_5015_50150201_204_dialog_content = "Siobhan, si tienes menos discusiones con ellos...",
  ui_story_5015_50150201_205_dialog_content = "Rubí, eso es suficiente. Entiendo claramente nuestra situación, y estoy seguro de que Florine también.",
  ui_story_5015_50150201_206_dialog_content = "Nuestra mayor prioridad es definitivamente encontrar una salida.",
  ui_story_5015_50150201_207_dialog_content = "Por lo tanto, no haremos nada demasiado extremo. ¿Está de acuerdo conmigo, señorita Florine?",
  ui_story_5015_50150201_208_dialog_content = "Sí estoy de acuerdo.",
  ui_story_5015_50150201_209_dialog_content = "¿Qué debemos hacer si el Mayordomo realmente se ha quedado dormido?",
  ui_story_5015_50150201_210_dialog_content = "Somos tantos... Estoy seguro de que encontraremos la manera.",
  ui_story_5015_50150201_211_dialog_content = "Siempre podemos volver a los pisos superiores y continuar con la investigación de Seamus. Eventualmente encontraremos la salida.",
  ui_story_5015_50150201_212_dialog_content = "Si hay más terremotos, este lugar será destruido antes de encontrar una salida.",
  ui_story_5015_50150201_213_dialog_content = "Razón de más para volver a los pisos superiores. Al menos hay ropa hermosa, comida sabrosa y hermosos paisajes allí.",
  ui_story_5015_50150201_214_dialog_content = "¿No quieres quedarte aquí en absoluto? ¿Es el mundo exterior realmente tan bueno?",
  ui_story_5015_50150201_215_dialog_content = "Lo sabrás una vez que lo experimentes tú mismo.",
  ui_story_5015_50150201_216_dialog_content = "La ubicación que me dio el mayordomo debería estar más adelante.",
  ui_story_5015_50150201_217_dialog_content = "Por fin...",
  ui_story_5015_50150201_218_dialog_content = "¡Oh, no! ¡Hay eclipses por aquí!",
  ui_story_5015_50150201_219_dialog_content = "¡Todos, prepárense para luchar!",
  ui_story_5015_50150201_220_dialog_content = "Es... ¿Es posible que los Eclipsites puedan atacar al Mayordomo?",
  ui_story_5015_50150201_221_dialog_content = "Eso es imposible, ya que los Eclipsites y los droides no se atacan activamente entre sí. ¿Estoy en lo cierto, Valencia?",
  ui_story_5015_50150201_222_dialog_content = "Sí, nunca había visto que eso sucediera antes.",
  ui_story_5015_50150201_223_dialog_content = "¿No pueden dejar de charlar antes de una pelea?",
  ui_story_5015_50150201_224_dialog_content = "¡Soy el primero otra vez! ¡Cargo!",
  ui_story_5015_50150201_225_dialog_content = "Parece que se están retirando...",
  ui_story_5015_50150201_226_dialog_content = "Por fin...",
  ui_story_5015_50150201_227_dialog_content = "Por fin nos volvemos a encontrar...",
  ui_story_5015_50150301_1_dialog_content = "<color=#e8d9bb>Gretel, Valencia, PlayerName, Hola.</color>",
  ui_story_5015_50150301_2_dialog_content = "¿Por qué no pudimos comunicarnos con usted? Pensamos que eras...",
  ui_story_5015_50150301_3_dialog_content = "<color=#e8d9bb>Estoy bien... Solo necesito... tiempo... para recuperarme... ¿Estás bien?</color>",
  ui_story_5015_50150301_4_dialog_content = "Me encontré con ellos de camino al núcleo de energía... Mi hermana no me dejaba ir.",
  ui_story_5015_50150301_5_dialog_content = "Mayordomo, ¿de verdad crees que está bien pedirle a Gretel que haga algo tan peligroso?",
  ui_story_5015_50150301_6_dialog_content = "<color=#e8d9bb>Si el terremoto... Si el núcleo... se daña, entonces las cosas serán realmente malas.</color>",
  ui_story_5015_50150301_7_dialog_content = "Esa persona dijo que es tu amigo. ¿Es eso cierto?",
  ui_story_5015_50150301_8_dialog_content = "<color=#e8d9bb>Sí... PlayerName es un caelestita, amigo de la ciudad.</color>",
  ui_story_5015_50150301_9_dialog_content = "Mayordomo, nos encontramos de nuevo.",
  ui_story_5015_50150301_10_dialog_content = "<color=#e8d9bb>Saludos Caelestita.</color>",
  ui_story_5015_50150301_11_dialog_content = "Las máquinas detrás de ti son tu verdadero yo, ¿verdad?",
  ui_story_5015_50150301_12_dialog_content = "Oye, dejemos las formalidades y vayamos al grano. ¡Yo hablaré!",
  ui_story_5015_50150301_13_dialog_content = "Mayordomo, solo queremos irnos de este lugar ahora. ¿Dónde está la salida?",
  ui_story_5015_50150301_14_dialog_content = "...",
  ui_story_5015_50150301_15_dialog_content = "<color=#e8d9bb>Lo siento, permiso denegado. No puedo responder a esta pregunta.</color>",
  ui_story_5015_50150301_16_dialog_content = "Preguntaré entonces. Mayordomo, ¿cómo podemos dejar este lugar?",
  ui_story_5015_50150301_17_dialog_content = "<color=#e8d9bb>No tengo ninguna... información sobre cómo salir de la ciudad.</color>",
  ui_story_5015_50150301_18_dialog_content = "¿Dónde podemos averiguarlo?",
  ui_story_5015_50150301_19_dialog_content = "<color=#e8d9bb>Lo siento... Permiso denegado... No puedo responder a esta pregunta.</color>",
  ui_story_5015_50150301_20_dialog_content = "Mayordomo, ¿qué necesita que hagamos?",
  ui_story_5015_50150301_21_dialog_content = "<color=#e8d9bb>Puedes vivir... con seguridad... en la ciudad...</color>",
  ui_story_5015_50150301_22_dialog_content = "<color=#e8d9bb>Pero recuerda seguir las reglas... No pongas en peligro la seguridad de la ciudad.</color>",
  ui_story_5015_50150301_23_dialog_content = "Recién hoy descubrí que los Eclipsites no atacan a los residentes.",
  ui_story_5015_50150301_24_dialog_content = "Mayordomo, ¿por qué no dejaste que mamá y papá se convirtieran en residentes?",
  ui_story_5015_50150301_25_dialog_content = "¡Si los hubieras dejado, no habrían muerto!",
  ui_story_5015_50150301_26_dialog_content = "Hermana...",
  ui_story_5015_50150301_27_dialog_content = "<color=#e8d9bb>Valencia, no fijé los criterios de aprobación para los residentes.</color>",
  ui_story_5015_50150301_28_dialog_content = "<color=#e8d9bb>Debo insistir... Según los cálculos... La tarea más importante que tenemos entre manos es reparar el núcleo de energía.</color>",
  ui_story_5015_50150301_29_dialog_content = "<color=#e8d9bb>Si no se repara, la ciudad puede colapsar por completo en menos de 100 réplicas.</color>",
  ui_story_5015_50150301_30_dialog_content = "Olvídalo. Dejemos de jugar a este juego de adivinanzas y solo busquemos la información.",
  ui_story_5015_50150301_31_dialog_content = "Es una pena que realmente no entienda la inteligencia artificial...",
  ui_story_5015_50150301_32_dialog_content = "PlayerName, ¿qué podías sentir de las máquinas de Butler?",
  ui_story_5015_50150301_33_dialog_content = "No, no pude sentir nada.",
  ui_story_5015_50150301_34_dialog_content = "¡Espera, puedo sentir eclipses!",
  ui_story_5015_50150301_35_dialog_content = "¿Por qué hay tantos eclipses?",
  ui_story_5015_50150301_36_dialog_content = "Florine, ven conmigo para atraer la atención de los Eclipsites desde un costado.",
  ui_story_5015_50150301_37_dialog_content = "Ruby, lidera a los demás y prepárate para abrirte paso.",
  ui_story_5015_50150301_38_dialog_content = "¡Cuidado! ¡Gretel!",
  ui_story_5015_50150301_39_dialog_content = "¿Los Eclipsites realmente están atacando a Gretel?",
  ui_story_5015_50150301_40_dialog_content = "Valencia, Gretel, acérquense a mí.",
  ui_story_5015_50150301_41_dialog_content = "No te preocupes, estoy bien, Valencia.",
  ui_story_5015_50150301_42_dialog_content = "Conseguiré que los droides te ayuden, Ruby.",
  ui_story_5015_50150301_43_dialog_content = "¡Increíble!",
  ui_story_5015_50150301_44_dialog_content = "¡Los eclipses se están retirando!",
  ui_story_5015_50150301_45_dialog_content = "Mayordomo, ¿por qué los eclipses atacan a Gretel?",
  ui_story_5015_50150301_46_dialog_content = "¿Le quitaste el estatus de residente a Gretel?",
  ui_story_5015_50150301_47_dialog_content = "<color=#e8d9bb>No, no lo hice.</color>",
  ui_story_5015_50150301_48_dialog_content = "¡Mentiroso!",
  ui_story_5015_50150301_49_dialog_content = "PlayerName, no creo que esté mintiendo.",
  ui_story_5015_50150301_50_dialog_content = "Gretel todavía puede ordenar a los droides que peleen, por lo que sigue siendo residente.",
  ui_story_5015_50150301_51_dialog_content = "Y los droides no nos están atacando.",
  ui_story_5015_50150301_52_dialog_content = "Entonces, no nos hemos convertido en los enemigos de la ciudad. ¿Tengo razón, mayordomo?",
  ui_story_5015_50150301_53_dialog_content = "<color=#e8d9bb>No digo mentiras.</color>",
  ui_story_5015_50150301_54_dialog_content = "De cualquier manera, ahora que los Eclipsites han comenzado a atacar a los residentes, ¿significa esto que se ha vuelto aún más peligroso?",
  ui_story_5015_50150301_55_dialog_content = "<color=#e8d9bb>Según mis cálculos... Si no te doy información relevante...</color>",
  ui_story_5015_50150301_56_dialog_content = "<color=#e8d9bb>Realmente estarás en mayor peligro.</color>",
  ui_story_5015_50150301_57_dialog_content = "<color=#e8d9bb>Trataré de decírtelo de una manera que puedas... entender.</color>",
  ui_story_5015_50150301_58_dialog_content = "<color=#e8d9bb>De hecho, los eclipses fueron creados por esta ciudad... Lo he verificado por completo recientemente.</color>",
  ui_story_5015_50150301_59_dialog_content = "<color=#e8d9bb>Después de despertarme... me di cuenta de que todos los residentes habían desaparecido.</color>",
  ui_story_5015_50150301_60_dialog_content = "<color=#e8d9bb>Y había una nueva especie foránea en la ciudad... los Eclipsites.</color>",
  ui_story_5015_50150301_61_dialog_content = "<color=#e8d9bb>No sabía... qué pasó.</color>",
  ui_story_5015_50150301_62_dialog_content = "<color=#e8d9bb>Pero según alguna información, los Eclipsites atacaron a los residentes... resultando en su eliminación.</color>",
  ui_story_5015_50150301_63_dialog_content = "Supuse que había una falla en el sistema de gestión de la ciudad... que llevó a los Eclipsites a atravesar la barrera e invadir este lugar.",
  ui_story_5015_50150301_64_dialog_content = "Los pueblos antiguos que no estaban protegidos por los droides eran...",
  ui_story_5015_50150301_65_dialog_content = "<color=#e8d9bb>Existe esta posibilidad... pero no pude encontrar ninguna información.</color>",
  ui_story_5015_50150301_66_dialog_content = "<color=#e8d9bb>Siempre que quiero buscar el origen de los Eclipsites... no puedo continuar porque no tengo la autorización requerida.</color>",
  ui_story_5015_50150301_67_dialog_content = "<color=#e8d9bb>Siempre he estado esperando que otros módulos despierten.</color>",
  ui_story_5015_50150301_68_dialog_content = "<color=#e8d9bb>Abby que tiene más conocimientos biológicos... Hughes, que está a cargo del sistema de combate, o incluso...</color>",
  ui_story_5015_50150301_69_dialog_content = "<color=#e8d9bb>Después de eso, llegaron Seamus y los demás.</color>",
  ui_story_5015_50150301_70_dialog_content = "<color=#e8d9bb>Me di cuenta de que el comportamiento de los Eclipsites... seguía una lógica similar a la de los droides.</color>",
  ui_story_5015_50150301_71_dialog_content = "Lo sé, ¿por qué no intentas marcar a los Eclipsites como enemigos de la ciudad?",
  ui_story_5015_50150301_72_dialog_content = "<color=#e8d9bb>Según mis cálculos... Si los Eclipsites están marcados como enemigos.</color>",
  ui_story_5015_50150301_73_dialog_content = "<color=#e8d9bb>Se utilizarían más recursos para el combate... A largo plazo, esto sería más peligroso para la ciudad.</color>",
  ui_story_5015_50150301_74_dialog_content = "<color=#e8d9bb>No mataremos fácilmente a ninguna criatura... incluidos los aurorianos y los eclipsitas.</color>",
  ui_story_5015_50150301_75_dialog_content = "Hemos visto un mecanismo de protección similar llamado la ley en otra ciudad subterránea.",
  ui_story_5015_50150301_76_dialog_content = "Quizás esta era una de las preocupaciones de los pueblos antiguos sobre la inteligencia artificial.",
  ui_story_5015_50150301_77_dialog_content = "<color=#e8d9bb>Después, ordené y analicé la información fragmentada...</color>",
  ui_story_5015_50150301_78_dialog_content = "<color=#e8d9bb>Me di cuenta de que el Eclipsite y los humanos antiguos parecían compartir muchas características similares.</color>",
  ui_story_5015_50150301_79_dialog_content = "¡¿Esperar lo?! ¿Los eclipses y los humanos antiguos tenían muchas similitudes?",
  ui_story_5015_50150301_80_dialog_content = "<color=#e8d9bb>Algunas características fueron seleccionadas de forma antinatural y realizadas a través de la evolución.</color>",
  ui_story_5015_50150301_81_dialog_content = "<color=#e8d9bb>Según los archivos dejados por los antiguos humanos, los Eclipsites de hoy parecen haber pasado por lo mismo...</color>",
  ui_story_5015_50150301_82_dialog_content = "Modificación. Eran criaturas modificadas artificialmente.",
  ui_story_5015_50150301_83_dialog_content = "Eso hace las cosas más simples. Abby, el módulo biológico que se encarga de nutrir la vida humana...",
  ui_story_5015_50150301_84_dialog_content = "Detuvo o no pudo continuar creando humanos antiguos, sino que comenzó a desarrollar los Eclipsites en su lugar.",
  ui_story_5015_50150301_85_dialog_content = "¿Cómo pasó esto?",
  ui_story_5015_50150301_86_dialog_content = "<color=#e8d9bb>Señorita Siobhan, es muy inteligente... Me recuerda a Seamus.</color>",
  ui_story_5015_50150301_87_dialog_content = "Acabo de hacer una deducción simple basada en la información que proporcionó.",
  ui_story_5015_50150301_88_dialog_content = "Todos sabemos que cada ciudad subterránea tiene un sistema a cargo de la reproducción... Oh, Seamus probablemente no lo sabía.",
  ui_story_5015_50150301_89_dialog_content = "Este fue un descubrimiento hecho mientras investigaba otras ruinas en los últimos años.",
  ui_story_5015_50150301_90_dialog_content = "Lo que significa que Seamus no tendría conocimiento de esto, o de lo contrario habría aprendido la verdad de este lugar hace mucho tiempo.",
  ui_story_5015_50150301_91_dialog_content = "PlayerName, para evitar su propia extinción, los antiguos humanos...",
  ui_story_5015_50150301_92_dialog_content = "... tenían un sistema de respaldo a cargo de la reproducción y la educación en casi todas las ciudades subterráneas.",
  ui_story_5015_50150301_93_dialog_content = "Como Abby y Uma aquí.",
  ui_story_5015_50150301_94_dialog_content = "Este es el caso de Gannon y R - Ruins–",
  ui_story_5015_50150301_95_dialog_content = "En la R - Ruinas, también descubrimos un sistema que podría usarse para regresar a la superficie.",
  ui_story_5015_50150301_96_dialog_content = "Según la información, esto se utilizó para monitorear la ecología de la superficie y–",
  ui_story_5015_50150301_97_dialog_content = "Según la ecología de la superficie...",
  ui_story_5015_50150301_98_dialog_content = "El sistema de reproducción haría evolucionar a las futuras generaciones de humanos antiguos para adaptarse a los cambios.",
  ui_story_5015_50150301_99_dialog_content = "<color=#e8d9bb>Sí tienes razón. Myers también ha desaparecido...</color>",
  ui_story_5015_50150301_100_dialog_content = "Como esperaba... Si hay un sistema que conduce a la superficie, entonces también debe haber un pasaje que conduce a la superficie.",
  ui_story_5015_50150301_101_dialog_content = "Debemos encontrarlo.",
  ui_story_5015_50150301_102_dialog_content = "Si los eclipses siguen evolucionando, probablemente seremos eliminados antes de que podamos encontrar la salida.",
  ui_story_5015_50150301_103_dialog_content = "En ese caso, Mayordomo, puedes intentar contactar a Abby.",
  ui_story_5015_50150301_104_dialog_content = "¿No se resolverá el problema si podemos convencer a Abby de que detenga esta peligrosa actividad?",
  ui_story_5015_50150301_105_dialog_content = "<color=#e8d9bb>Te lo dije... No puedo conectarme con Abby.</color>",
  ui_story_5015_50150301_106_dialog_content = "¡Entonces deberías destruirlo!",
  ui_story_5015_50150301_107_dialog_content = "<color=#e8d9bb>Los módulos tienen... estrictamente prohibido atacarse unos a otros.</color>",
  ui_story_5015_50150301_108_dialog_content = "...",
  ui_story_5015_50150301_109_dialog_content = "Señorita Siobhan, la lógica del mayordomo ya no tiene sentido para mí.",
  ui_story_5015_50150301_110_dialog_content = "Ha sufrido el desgaste de incontables años... Olvídalo, tal vez podamos tratar al mayordomo como un paciente paranoico.",
  ui_story_5015_50150301_111_dialog_content = "Suspiro, busquemos el sistema que se puede usar para volver a la superficie.",
  ui_story_5015_50150301_112_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5015_50150301_113_dialog_content = "¡Oh no, es otro terremoto!",
  ui_story_5015_50150301_114_dialog_content = "¡Cuidado con los objetos que caen!",
  ui_story_5015_50150301_115_dialog_content = "Gah... ¡Gah...!",
  ui_story_5015_50150301_116_dialog_content = "¡Los eclipses han llegado hasta aquí!",
  ui_story_5015_50150301_117_dialog_content = "<color=#e8d9bb>Peligro... Abby es...</color>",
  ui_story_5015_50150301_118_dialog_content = "¡Rugido!",
  ui_story_5015_50150301_119_dialog_content = "¿Qué pasa con estos eclipses? ¿Por qué están cobrando sin ninguna consideración por sus vidas?",
  ui_story_5015_50150301_120_dialog_content = "¡Ruby, Florine, paren esos eclipses!",
  ui_story_5015_50150301_121_dialog_content = "Sucedió antes, cuando llegamos al centro de datos de Butler...",
  ui_story_5015_50150301_122_dialog_content = "Estos eclipses nos tratan a todos, incluido el mayordomo, como a sus enemigos.",
  ui_story_5015_50150301_123_dialog_content = "Yo daré las órdenes. ¡Acaba con ellos lo antes posible!",
  ui_story_5015_50150301_124_dialog_content = "¡Graaaaaagh!",
  ui_story_5015_50150301_125_dialog_content = "¡Torrente rápido!",
  ui_story_5015_50150301_126_dialog_content = "¡Déjame intentarlo!",
  ui_story_5015_50150301_127_dialog_content = "¡Golpe de murciélago súper duper!",
  ui_story_5015_50150301_128_dialog_content = "Grrr...",
  ui_story_5015_50150301_129_dialog_content = "Por fin ha terminado...",
  ui_story_5015_50150301_130_dialog_content = "Iré a ver cómo está el mayordomo.",
  ui_story_5015_50150301_131_dialog_content = "<color=#e8d9bb>No te preocupes... he reanudado el funcionamiento normal.</color>",
  ui_story_5015_50150301_132_dialog_content = "Pensé que los módulos no pueden atacarse entre sí. ¿Por qué los eclipses de Abby...",
  ui_story_5015_50150301_133_dialog_content = "<color=#e8d9bb>Abby ha obtenido mayor... autoridad.</color>",
  ui_story_5015_50150301_134_dialog_content = "<color=#e8d9bb>Ella está tomando aún más derechos de control.</color>",
  ui_story_5015_50150301_135_dialog_content = "<color=#e8d9bb>La mayoría de las máquinas... están fuera de mi control ahora...</color>",
  ui_story_5015_50150301_136_dialog_content = "¿Abby está tomando autoridad?",
  ui_story_5015_50150301_137_dialog_content = "¿Roba cosas bajo nuestro reloj...? ¡¿Dónde está esta Abby?!",
  ui_story_5015_50150301_138_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_5015_50150301_139_dialog_content = "<color=#e8d9bb>A... es... es... es...</color>",
  ui_story_5015_50150301_140_dialog_content = "<color=#e8d9bb>Todos se dirigen en una dirección... Ahí es donde Abby y la energía... están.</color>",
  ui_story_5015_50150301_141_dialog_content = "¿Qué dirección es esa?",
  ui_story_5015_50150301_142_dialog_content = "El núcleo de energía...",
  ui_story_5015_50150301_143_dialog_content = "<size=45><color=#FFB400>Estrellas de la alquimia.</color></size>",
  ui_story_5015_50150401_1_dialog_content = "¿Estrellas de la alquimia?",
  ui_story_5015_50150401_2_dialog_content = "<color=#e8d9bb>Este es el... nombre del núcleo de energía.</color>",
  ui_story_5015_50150401_3_dialog_content = "El núcleo de energía proporciona energía para toda la ciudad subterránea.",
  ui_story_5015_50150401_4_dialog_content = "¿Por qué Abby está haciendo que los droides y los eclipses vayan allí?",
  ui_story_5015_50150401_5_dialog_content = "<color=#e8d9bb>Abby está tratando de reparar el núcleo de energía.</color>",
  ui_story_5015_50150401_6_dialog_content = "¿Puede Abby reparar el núcleo de energía?",
  ui_story_5015_50150401_7_dialog_content = "<color=#e8d9bb>Actualmente estoy calculando... la posibilidad...</color>",
  ui_story_5015_50150401_8_dialog_content = "<color=#e8d9bb>Abby tiene autoridad para acceder a... más información.</color>",
  ui_story_5015_50150401_9_dialog_content = "En otras palabras, tiene la información necesaria para reparar el núcleo de energía que el mayordomo no tiene...",
  ui_story_5015_50150401_10_dialog_content = "Y ahora ha adquirido la autorización de mantenimiento, por lo que está enviando a los droides allí.",
  ui_story_5015_50150401_11_dialog_content = "Si Abby puede estabilizar las estrellas de Alchemy...",
  ui_story_5015_50150401_12_dialog_content = "¡Entonces nuestra ciudad puede operar normalmente!",
  ui_story_5015_50150401_13_dialog_content = "Si ese es el caso, podemos hacer que Honcho Sinsa venga y elimine todos los Eclipsites aquí.",
  ui_story_5015_50150401_14_dialog_content = "¡Entonces todos podemos vivir aquí!",
  ui_story_5015_50150401_15_dialog_content = "¡Después de eso, no tendremos que quedarnos en el desierto y que nos arrojen arena en la cara todo el día!",
  ui_story_5015_50150401_16_dialog_content = "¡No tienes permitido venir!",
  ui_story_5015_50150401_17_dialog_content = "Valencia, ¿podremos quedarnos aquí si se arregla el núcleo energético?",
  ui_story_5015_50150401_18_dialog_content = "Gretel...",
  ui_story_5015_50150401_19_dialog_content = "También hay mucha información valiosa sobre tecnología antigua aquí...",
  ui_story_5015_50150401_20_dialog_content = "Habrá beneficios asombrosos para todo el continente si podemos estudiar y usar esto...",
  ui_story_5015_50150401_21_dialog_content = "Nada bueno vendrá sin importar lo que hagan estas máquinas sin fe y sin alma.",
  ui_story_5015_50150401_22_dialog_content = "Érica tiene razón! Eres demasiado ingenuo.",
  ui_story_5015_50150401_23_dialog_content = "Mira la inteligencia artificial aquí–",
  ui_story_5015_50150401_24_dialog_content = "Uno tiene una lógica confusa y no puede disponer de un módulo de inteligencia que sigue modificando Eclipsites.",
  ui_story_5015_50150401_25_dialog_content = "Y otro ha abandonado su configuración original y comenzó a estudiar y desarrollar Eclipsites en su lugar.",
  ui_story_5015_50150401_26_dialog_content = "¿De verdad esperas que creen un lugar ideal para que vivan los aurorianos?",
  ui_story_5015_50150401_27_dialog_content = "¿No deberíamos pensar en lo que sucedería si Abby no puede estabilizar las estrellas de Alchemy?",
  ui_story_5015_50150401_28_dialog_content = "Mayordomo, ¿qué pasará si Abby no puede estabilizar las estrellas de Alquimia?",
  ui_story_5015_50150401_29_dialog_content = "<color=#e8d9bb>Las operaciones de alta autoridad de Abby...</color>",
  ui_story_5015_50150401_30_dialog_content = "<color=#e8d9bb>aumentará la carga operativa de las estrellas Alchemy, lo cual es muy peligroso.</color>",
  ui_story_5015_50150401_31_dialog_content = "¿Se enteró que? ¡Este lugar se volverá aún más peligroso si Abby falla!",
  ui_story_5015_50150401_32_dialog_content = "No pensemos en lo que pasará si falla. ¿Saldrán bien las cosas para nosotros si tiene éxito?",
  ui_story_5015_50150401_33_dialog_content = "Puedes preguntarle al mayordomo qué le sucederá al mayordomo si Abby arregla el núcleo.",
  ui_story_5015_50150401_34_dialog_content = "Mayordomo, ¿te afectará si Abby arregla el núcleo?",
  ui_story_5015_50150401_35_dialog_content = "<color=#e8d9bb>Mi autoridad caerá aún más bajo.</color>",
  ui_story_5015_50150401_36_dialog_content = "<color=#e8d9bb>Yo... podría dejar de operar.</color>",
  ui_story_5015_50150401_37_dialog_content = "En ese caso, nosotros...",
  ui_story_5015_50150401_38_dialog_content = "<color=#e8d9bb>Supongo que enfrentarás... peligros aún mayores.</color>",
  ui_story_5015_50150401_39_dialog_content = "<color=#e8d9bb>Abby usará... la energía para <color=#FFB400>desarrollar eclipses</color>.</color>",
  ui_story_5015_50150401_40_dialog_content = "¡No podemos dejar que Abby arregle el núcleo!",
  ui_story_5015_50150401_41_dialog_content = "Es obvio que la inteligencia artificial modificando Eclipsites no abrirá un camino para que nadie de aquí se vaya.",
  ui_story_5015_50150401_42_dialog_content = "Es más probable que cree eclipses aún más fuertes y los envíe a la superficie.",
  ui_story_5015_50150401_43_dialog_content = "Una vez que la tierra se llene de terroríficos eclipses de orígenes desconocidos, los aurorianos se enfrentarán a desafíos más duros que nunca.",
  ui_story_5015_50150401_44_dialog_content = "Aun así, todos todavía quieren llevarse bien con la inteligencia artificial.",
  ui_story_5015_50150401_45_dialog_content = "No lo entiendo en absoluto.",
  ui_story_5015_50150401_46_dialog_content = "Espero que puedas dejar de lado tu ingenuidad inducida por el fanatismo, volver a la realidad y pensar bien en lo que debemos lograr a continuación.",
  ui_story_5015_50150401_47_dialog_content = "Deberíamos detener a Abby ahora.",
  ui_story_5015_50150401_48_dialog_content = "Entiendo lo que dices.",
  ui_story_5015_50150401_49_dialog_content = "Gretel, tienes la máxima autoridad entre nosotros. ¿Puedes pedirle al mayordomo que nos muestre el camino?",
  ui_story_5015_50150401_50_dialog_content = "Si. Mayordomo, queremos ir al lugar llamado Alchemy stars.",
  ui_story_5015_50150401_51_dialog_content = "<color=#e8d9bb>Afirmativo... Gretel...</color>",
  ui_story_5015_50150401_52_dialog_content = "<color=#e8d9bb>Por delante de nosotros. Estamos a punto de entrar... en el área del núcleo de energía.</color>",
  ui_story_5015_50150401_53_dialog_content = "¡Me estoy poniendo nervioso, sabiendo que estoy a punto de conocer a la legendaria Abby y al núcleo de energía!",
  ui_story_5015_50150401_54_dialog_content = "Ruby... parece haber señales de los droides más adelante.",
  ui_story_5015_50150401_55_dialog_content = "Ah, okey. Hagamos un seguimiento.",
  ui_story_5015_50150401_56_dialog_content = "Puedo sentir un Darkflow especialmente denso más adelante.",
  ui_story_5015_50150401_57_dialog_content = "hacer el plan, PlayerName.",
  ui_story_5015_50150401_58_dialog_content = "Todos, necesitamos eliminar todos los Eclipsites y droides aquí primero.",
  ui_story_5015_50150401_59_dialog_content = "Esos droides podrían estar bajo el control de Abby.",
  ui_story_5015_50150401_60_dialog_content = "¡Todos, prepárense para pelear!",
  ui_story_5015_50150401_61_dialog_content = "¡Golpéalo!",
  ui_story_5015_50150401_62_dialog_content = "¡Graagh!",
  ui_story_5015_50150401_63_dialog_content = "¡Ruby está tan emocionada por pelear como siempre!",
  ui_story_5015_50150401_64_dialog_content = "¡No puedo quedarme atrás!",
  ui_story_5015_50150401_65_dialog_content = "Espada ardiente!",
  ui_story_5015_50150401_66_dialog_content = "Grrr... Gargh...",
  ui_story_5015_50150401_67_dialog_content = "¿Sientes una sensación de opresión?",
  ui_story_5015_50150401_68_dialog_content = "Se siente como si el aire que nos rodea nos estrujara...",
  ui_story_5015_50150401_69_dialog_content = "Es... Podría ser porque el suministro de energía de toda la ciudad subterránea... está por aquí.",
  ui_story_5015_50150401_70_dialog_content = "¡¡Graaaaaah!!",
  ui_story_5015_50150401_71_dialog_content = "¡Eclipse detrás de ti, Rouge! Fuera del camino-",
  ui_story_5015_50150401_72_dialog_content = "¡Toma esto!",
  ui_story_5015_50150401_73_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5015_50150401_74_dialog_content = "Wow, creo que no usé toda mi fuerza... ¿Es esto lo que puedo hacer con la mitad de mi poder ahora...?",
  ui_story_5015_50150401_75_dialog_content = "Rouge, ¿viste cuánto he mejorado?",
  ui_story_5015_50150401_76_dialog_content = "¡Rubí, hay un terremoto!",
  ui_story_5015_50150401_77_dialog_content = "¡Escondámonos allí!",
  ui_story_5015_50150401_78_dialog_content = "Puedo sentir la energía en el entorno cambiando...",
  ui_story_5015_50150401_79_dialog_content = "¡La energía se está volviendo más densa rápidamente!",
  ui_story_5015_50150401_80_dialog_content = "¿Podría haber algo mal con las estrellas de Alchemy?",
  ui_story_5015_50150401_81_dialog_content = "Estoy tratando de sentirlo mejor...",
  ui_story_5015_50150401_82_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5015_50150401_83_dialog_content = "Urgh ... * tos-tos *",
  ui_story_5015_50150401_84_dialog_content = "PlayerName¡Te sangra la nariz! ¡Deja de sentir ahora!",
  ui_story_5015_50150401_85_dialog_content = "<color=#e8d9bb>¡Grieta! ¡¡Auge!!</color>",
  ui_story_5015_50150401_86_dialog_content = "... Eres... tú... ¿Por qué eres tú otra vez?",
  ui_story_5015_50150401_87_dialog_content = "¿Hemos establecido una conexión telepática?",
  ui_story_5015_50150401_88_dialog_content = "<color=#e8d9bb>Sí, PlayerName. Es porque usaste tu habilidad psíquica de nuevo que pudimos...</color>",
  ui_story_5015_50150401_89_dialog_content = "No, en realidad no estaba tratando de establecer una conexión contigo.",
  ui_story_5015_50150401_90_dialog_content = "Mayordomo, ¿puedes ver lo que les pasó a Vice ya los demás? Estoy preocupado por ellos después del terremoto...",
  ui_story_5015_50150401_91_dialog_content = "<color=#e8d9bb>No te preocupes, tus amigos no están heridos.</color>",
  ui_story_5015_50150401_92_dialog_content = "<color=#e8d9bb>Tu eficiencia de combate es increíble. Casi todos los Eclipsites y droides en el área han sido eliminados.</color>",
  ui_story_5015_50150401_93_dialog_content = "¡Eso es maravilloso!",
  ui_story_5015_50150401_94_dialog_content = "<color=#e8d9bb>Tu corazón todavía estaba con tus compañeros incluso cuando estás inconsciente. Tu espíritu es muy admirable.</color>",
  ui_story_5015_50150401_95_dialog_content = "Mi espíritu no es particularmente admirable. ¿No es normal estar preocupado por tus amigos?",
  ui_story_5015_50150401_96_dialog_content = "Debido a que tenemos emociones, compartimos la felicidad de los demás y nos preocupamos por la situación de los demás.",
  ui_story_5015_50150401_97_dialog_content = "Deberías poder sentir eso también.",
  ui_story_5015_50150401_98_dialog_content = "<color=#e8d9bb>Si. Puedo determinar cómo se siente una persona analizando sus expresiones faciales, palabras y lenguaje corporal.</color>",
  ui_story_5015_50150401_99_dialog_content = "Sentir no es algo que puedas determinar... Oye, ¿no me digas que no entiendes las emociones?",
  ui_story_5015_50150401_100_dialog_content = "Hiciste a Gretel residente de esta ciudad... ¿No fue la emoción un factor?",
  ui_story_5015_50150401_101_dialog_content = "<color=#e8d9bb>Tus palabras me confundieron.</color>",
  ui_story_5015_50150401_102_dialog_content = "<color=#e8d9bb>Hice a Gretel residente porque cumplió con los criterios de la próxima generación de residentes.</color>",
  ui_story_5015_50150401_103_dialog_content = "<color=#e8d9bb>No tenía nada que ver con las emociones.</color>",
  ui_story_5015_50150401_104_dialog_content = "Pero has estado cuidando a Gretel durante tanto tiempo...",
  ui_story_5015_50150401_105_dialog_content = "¿Gretel no es alguien especial para ti?",
  ui_story_5015_50150401_106_dialog_content = "También están el Sr. y la Sra. Seamus y Valencia... Dijiste que protegiste a los hijos del Sr. y la Sra. Seamus porque fallaste en protegerlos.",
  ui_story_5015_50150401_107_dialog_content = "Pensé que tenías sentimientos por ellos...",
  ui_story_5015_50150401_108_dialog_content = "<color=#e8d9bb>El Sr. y la Sra. Seamus eran forasteros, como tú, así que no pude autenticarlos.</color>",
  ui_story_5015_50150401_109_dialog_content = "<color=#e8d9bb>Valencia no era lo suficientemente fuerte, y solo Gretel cumplía con los criterios de aprobación. Ya he explicado esto.</color>",
  ui_story_5015_50150401_110_dialog_content = "Pero tu programa fue establecido por los antiguos humanos. ¿Cómo pudieron prever el estandarte de los aurorianos actuales?",
  ui_story_5015_50150401_111_dialog_content = "Creo que usted mismo establece los criterios.",
  ui_story_5015_50150401_112_dialog_content = "Y el criterio estaba hecho a la medida de Gretel.",
  ui_story_5015_50150401_113_dialog_content = "Solo querías encontrar una razón para convertirla en residente.",
  ui_story_5015_50150401_114_dialog_content = "La razón es... que probablemente sea la única persona aquí que confía en ti con todo su corazón.",
  ui_story_5015_50150401_115_dialog_content = "<color=#e8d9bb>No entiendo lo que estás diciendo.</color>",
  ui_story_5015_50150401_116_dialog_content = "Una vez viví con una inteligencia artificial llamada Soroz durante 17 años.",
  ui_story_5015_50150401_117_dialog_content = "Teníamos un vínculo emocional especial, así que también pensé que tenías...",
  ui_story_5015_50150401_118_dialog_content = "<color=#e8d9bb>Lo siento, ese no es el caso...</color>",
  ui_story_5015_50150401_119_dialog_content = "<color=#e8d9bb>¡Bang... bang!</color>",
  ui_story_5015_50150401_120_dialog_content = "¿Por qué todo tiembla de repente?",
  ui_story_5015_50150401_121_dialog_content = "<color=#e8d9bb>Tus amigos están tratando de despertarte.</color>",
  ui_story_5015_50150401_122_dialog_content = "Oh cierto, se supone que debo estar inconsciente en este momento. I...",
  ui_story_5015_50150401_123_dialog_content = "<color=#e8d9bb>¡Bofetada!</color>",
  ui_story_5015_50150401_124_dialog_content = "PlayerName¡Finalmente estás despierto!",
  ui_story_5015_50150401_125_dialog_content = "Urgh, ¿por qué... me duele la cara?",
  ui_story_5015_50150401_126_dialog_content = "Huff, no menciones tu cara porque mi mano me duele aún más.",
  ui_story_5015_50150401_127_dialog_content = "Fuerzas tu habilidad durante el terremoto... luego caes inconsciente.",
  ui_story_5015_50150401_128_dialog_content = "Permaneciste inconsciente incluso después del terremoto, por lo que no tuvimos más remedio que dejar que Ruby despertarte, con un poco de violencia...",
  ui_story_5015_50150401_129_dialog_content = "Me caí... y establecí una conexión telepática con el mayordomo...",
  ui_story_5015_50150401_130_dialog_content = "¿Eh? ¿Adónde fue el mayordomo? ¿Pasó algo más...?",
  ui_story_5015_50150401_131_dialog_content = "Le preguntamos al Mayordomo sobre la situación actual después de acabar con todos los Eclipsites y droides.",
  ui_story_5015_50150401_132_dialog_content = "Las estrellas de Alchemy parecen estar en una condición estable por ahora.",
  ui_story_5015_50150401_133_dialog_content = "Pero quién sabe cuánto durará esta estabilidad. Debemos ayudar al mayordomo a apoderarse de una mayor autoridad de Abby...",
  ui_story_5015_50150401_134_dialog_content = "Entonces podemos reparar el núcleo de energía.",
  ui_story_5015_50150401_135_dialog_content = "Si podemos reparar el núcleo de energía, el mayordomo debería poder ayudarnos a abrir un camino hacia el exterior.",
  ui_story_5015_50150401_136_dialog_content = "Según Butler, su centro de datos y el centro de datos de Abby parecen tener diferentes mecanismos de defensa...",
  ui_story_5015_50150401_137_dialog_content = "Los terremotos han agrietado la barrera externa, por lo que ahora está protegida principalmente por eclipses.",
  ui_story_5015_50150401_138_dialog_content = "Si podemos eliminar a los enemigos allí, Butler podrá conectarse a su centro de datos y obtener una mayor autoridad.",
  ui_story_5015_50150401_139_dialog_content = "En resumen, nuestra próxima parada es el centro de datos de Abby:",
  ui_story_5015_50150401_140_dialog_content = "Tendremos que eliminar por completo esta inteligencia artificial creadora de Eclipsite.",
  ui_story_5015_50150401_141_dialog_content = "Valencia y los demás están explorando cerca con el mayordomo.",
  ui_story_5015_50150401_142_dialog_content = "Un momento, el centro de datos de Abby... ¿Está cerca del núcleo de energía?",
  ui_story_5015_50150401_143_dialog_content = "Sí, debemos alcanzarlos rápidamente. ¿Cómo te sientes ahora?",
  ui_story_5015_50150401_144_dialog_content = "Estoy bien. Vamos.",
  ui_story_5015_50150401_145_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5015_50150401_146_dialog_content = "¡Argh! ¡Es tan ruidoso! ¡¿Por qué este terremoto no terminará?!",
  ui_story_5015_50150401_147_dialog_content = "¿Abby sabe cómo arreglar esto? ¿Por qué parece que está empeorando?",
  ui_story_5015_50150401_148_dialog_content = "¡Llévame al centro de datos de Abby ahora, para que pueda hacer añicos todo lo que hay dentro!",
  ui_story_5015_50150501_1_dialog_content = "Uf, finalmente vamos a conocer a la inteligencia artificial que sigue modificando Eclipsites.",
  ui_story_5015_50150501_2_dialog_content = "Me pregunto por qué no nos hemos encontrado con Eclipsitas o droides en el camino.",
  ui_story_5015_50150501_3_dialog_content = "Abby probablemente se ha dado cuenta de adónde vamos...",
  ui_story_5015_50150501_4_dialog_content = "Así que probablemente envió a todos los droides y Eclipsites a su centro de datos para protegerse.",
  ui_story_5015_50150501_5_dialog_content = "Señorita Siobhan, tengo otras preguntas.",
  ui_story_5015_50150501_6_dialog_content = "Pregunta lejos.",
  ui_story_5015_50150501_7_dialog_content = "Cuando se diseñó Abby por primera vez, se diseñó para ayudar a los antiguos humanos a cambiar sus genes para adaptarse al medio ambiente...",
  ui_story_5015_50150501_8_dialog_content = "¿Por qué decidió más tarde estudiar y modificar los eclipses?",
  ui_story_5015_50150501_9_dialog_content = "Una crisis se abatió sobre esta ciudad subterránea. Todos los humanos antiguos desaparecieron de este lugar después de eso.",
  ui_story_5015_50150501_10_dialog_content = "Tal vez esa crisis hizo que los cálculos de Abby salieran mal.",
  ui_story_5015_50150501_11_dialog_content = "Quiero decir, Eclipsite todavía cuenta como criaturas biológicas, ¿verdad?",
  ui_story_5015_50150501_12_dialog_content = "Desde cambiar los genes de humanos antiguos hasta modificar Eclipsites...",
  ui_story_5015_50150501_13_dialog_content = "Tal vez simplemente no quiere negar el significado de su existencia.",
  ui_story_5015_50150501_14_dialog_content = "Señorita Siobhan, creo que las respuestas a esta pregunta son muy valiosas.",
  ui_story_5015_50150501_15_dialog_content = "Si podemos entenderlos, podemos evitar que otras inteligencias artificiales se confundan cuando están operando.",
  ui_story_5015_50150501_16_dialog_content = "Bueno.",
  ui_story_5015_50150501_17_dialog_content = "Es muy peligroso tratar de comprender los pensamientos de la inteligencia artificial.",
  ui_story_5015_50150501_18_dialog_content = "Mientras la tecnología siga desarrollándose, la inteligencia artificial eventualmente llegará a un punto más allá del alcance de todas las personas.",
  ui_story_5015_50150501_19_dialog_content = "Es casi seguro que se produzcan problemas una vez que las creaciones tecnológicas empiecen a funcionar por sí solas.",
  ui_story_5015_50150501_20_dialog_content = "Los investigadores siempre quieren saber el por qué y siguen mirando hacia atrás para investigar.",
  ui_story_5015_50150501_21_dialog_content = "Pero solo logran resolver una parte del problema con cada introspección y revisión que realizan.",
  ui_story_5015_50150501_22_dialog_content = "Estas creaciones tecnológicas nunca pueden ser completamente domesticadas.",
  ui_story_5015_50150501_23_dialog_content = "Una vez que surgen los problemas y causan graves consecuencias, es posible que ni siquiera tengamos tiempo para reflexionar.",
  ui_story_5015_50150501_24_dialog_content = "Siempre piensas que la Iglesia de Lumopolis está difundiendo su dogma... y que la División de Investigación de Herejes simplemente destruye cosas indiscriminadamente.",
  ui_story_5015_50150501_25_dialog_content = "Pero cuando te enfrentas a una inteligencia artificial como Abby... y su lógica indescriptiblemente confusa...",
  ui_story_5015_50150501_26_dialog_content = "¿No crees que eso da bastante miedo?",
  ui_story_5015_50150501_27_dialog_content = "Los aurorianos siempre deben permanecer temerosos, para no pisar el oscuro abismo.",
  ui_story_5015_50150501_28_dialog_content = "<color=#e8d9bb>Hemos llegado. El centro de datos de Abby está... al frente.</color>",
  ui_story_5015_50150501_29_dialog_content = "¿Es este el lugar?",
  ui_story_5015_50150501_30_dialog_content = "Parece casi lo mismo que el centro de datos de Butler.",
  ui_story_5015_50150501_31_dialog_content = "Grrr...",
  ui_story_5015_50150501_32_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_33_dialog_content = "¡Detener! No te acerques más por ahora.",
  ui_story_5015_50150501_34_dialog_content = "Siento muchos eclipses y droides... Están parados en el pasaje frente a nosotros.",
  ui_story_5015_50150501_35_dialog_content = "Son como soldados... Han formado líneas ordenadas... y nos están esperando.",
  ui_story_5015_50150501_36_dialog_content = "<color=#e8d9bb>Abby nos está esperando... para ir allí.</color>",
  ui_story_5015_50150501_37_dialog_content = "<color=#e8d9bb>Ella sabe lo que pretendo hacer.</color>",
  ui_story_5015_50150501_38_dialog_content = "¿Es posible que Abby sepa que quiere apoderarse de su autoridad?",
  ui_story_5015_50150501_39_dialog_content = "<color=#e8d9bb>Sí... Ha movilizado todos sus Eclipsitas y droides... y los ha colocado frente al centro de datos.</color>",
  ui_story_5015_50150501_40_dialog_content = "<color=#e8d9bb>Ella ya había... decidido destruirnos a todos.</color>",
  ui_story_5015_50150501_41_dialog_content = "Ha movilizado todos sus Eclipsites y droides y los ha hecho esperar por nosotros... Es casi como si estuviera anunciando que esta es la última batalla.",
  ui_story_5015_50150501_42_dialog_content = "Si fallamos...",
  ui_story_5015_50150501_43_dialog_content = "Entonces todos estamos condenados.",
  ui_story_5015_50150501_44_dialog_content = "Vamos. Esta es la última batalla.",
  ui_story_5015_50150501_45_dialog_content = "Este lugar no es tan grande, así que todos deben tener cuidado... PlayerName, se parará en la última fila y nos dirá qué hacer.",
  ui_story_5015_50150501_46_dialog_content = "No hay problema.",
  ui_story_5015_50150501_47_dialog_content = "¡Rugido!",
  ui_story_5015_50150501_48_dialog_content = "Los Eclipsites se están cargando, así que retrocedamos y usemos el pasaje angosto para desgastar su primera fila.",
  ui_story_5015_50150501_49_dialog_content = "¡Usa ataques a distancia!",
  ui_story_5015_50150501_50_dialog_content = "Entiendo. ¡Torrente rápido!",
  ui_story_5015_50150501_51_dialog_content = "¡Golpe de murciélago súper duper!",
  ui_story_5015_50150501_52_dialog_content = "¡Seguid así! Trate de no dejar que nos apresuren de inmediato. Mátalos grupo por grupo.",
  ui_story_5015_50150501_53_dialog_content = "¡Vigila tu salud porque habrá muchos eclipses!",
  ui_story_5015_50150501_54_dialog_content = "Siobhan y Florine, mantengan su lugar en la primera fila. No dejes que rompan nuestra formación.",
  ui_story_5015_50150501_55_dialog_content = "Rouge y Erica, estén siempre listas para apoyar a la primera fila e intercambiar lugares con ellas.",
  ui_story_5015_50150501_56_dialog_content = "Carleen, tu ataque es flexible... Recuerda, nuestro objetivo es usar el terreno para negar su ventaja numérica.",
  ui_story_5015_50150501_57_dialog_content = "Sí, esta estrategia es una buena elección.",
  ui_story_5015_50150501_58_dialog_content = "Veamos cuánto aguantamos... Hay demasiados.",
  ui_story_5015_50150501_59_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_60_dialog_content = "¿Aún puedes pelear? florina...",
  ui_story_5015_50150501_61_dialog_content = "Huff... Huff... Pero solo estamos luchando contra innumerables Eclipsites y un montón de droides...",
  ui_story_5015_50150501_62_dialog_content = "¿Tenemos otra opción que persistir?",
  ui_story_5015_50150501_63_dialog_content = "¡Graagh!",
  ui_story_5015_50150501_64_dialog_content = "Urgh... Esta es la primera vez que siento que mi arco y mis flechas son tan pesados...",
  ui_story_5015_50150501_65_dialog_content = "Estos eclipses son un fastidio... ¿Cuánto tiempo más tendremos que seguir luchando contra ellos?",
  ui_story_5015_50150501_66_dialog_content = "Lo que más me preocupa es... Si esto continúa, estaremos atrapados entre estos eclipses y otros nuevos que se acerquen a nosotros por la espalda.",
  ui_story_5015_50150501_67_dialog_content = "¡Hay muchos enemigos, pero debemos luchar con todo lo que tenemos!",
  ui_story_5015_50150501_68_dialog_content = "¡Ayudaré en el frente!",
  ui_story_5015_50150501_69_dialog_content = "¡Hermana, cuídate!",
  ui_story_5015_50150501_70_dialog_content = "¡Rugido!",
  ui_story_5015_50150501_71_dialog_content = "¡Siobhan, detrás de ti!",
  ui_story_5015_50150501_72_dialog_content = "Valencia... Gracias...",
  ui_story_5015_50150501_73_dialog_content = "¿Estás bien? Debes estar tan agotado después de luchar en el frente durante tanto tiempo...",
  ui_story_5015_50150501_74_dialog_content = "Estoy bien. Puedo seguir luchando.",
  ui_story_5015_50150501_75_dialog_content = "¿Podemos realmente ganar incluso si no nos damos por vencidos?",
  ui_story_5015_50150501_76_dialog_content = "Esos Eclipsites no tienen fin... No le temen a la muerte, y no se cansan... Todos estaremos...",
  ui_story_5015_50150501_77_dialog_content = "Nosotros, los soldados de Illumina, siempre lucharemos contra los Eclipsites sin importar cuán temibles sean...",
  ui_story_5015_50150501_78_dialog_content = "Siempre luchamos hasta el final.",
  ui_story_5015_50150501_79_dialog_content = "Tu padre también debe haber luchado hasta el final de esta manera.",
  ui_story_5015_50150501_80_dialog_content = "Para proteger a las personas detrás de nosotros que necesitan nuestra protección, luchemos hasta que caigamos.",
  ui_story_5015_50150501_81_dialog_content = "¡Si entiendo! Luchemos hasta el final, como mamá y papá...",
  ui_story_5015_50150501_82_dialog_content = "Valencia... Valencia... ¡Es demasiado peligroso por delante! ¡Regresar!",
  ui_story_5015_50150501_83_dialog_content = "<color=#e8d9bb>Detecté las emociones de Gretel... Kss...</color>",
  ui_story_5015_50150501_84_dialog_content = "<color=#e8d9bb>Yo... proporcionaré toda mi asistencia... incluso si me quedo sin...</color>",
  ui_story_5015_50150501_85_dialog_content = "Mira esos droides... ¡Sus movimientos se han vuelto más lentos!",
  ui_story_5015_50150501_86_dialog_content = "El mayordomo está peleando con Abby por el derecho a controlarlos. ¡Ataquemos ahora para debilitar el poder de Abby!",
  ui_story_5015_50150501_87_dialog_content = "Érica, ¡vamos!",
  ui_story_5015_50150501_88_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_89_dialog_content = "¡Mayordomo! ¡Mayordomo! Qué pasa... ¡¿Por qué sueltas tanto humo?!",
  ui_story_5015_50150501_90_dialog_content = "Su sistema debe estar sobrecargado jugando con los derechos de control...",
  ui_story_5015_50150501_91_dialog_content = "Boo-hoo... ¿Por qué está pasando esto? ¿Por qué todavía hay tantos eclipses...? Valencia... Mayordomo...",
  ui_story_5015_50150501_92_dialog_content = "¡E-todos morirán!",
  ui_story_5015_50150501_93_dialog_content = "PlayerName! ¡Piensa en algo! ¿No eres el Navegante? Con rapidez...",
  ui_story_5015_50150501_94_dialog_content = "Yo... Hay una última cosa que podemos intentar, pero es muy arriesgado... No quiero lastimarte.",
  ui_story_5015_50150501_95_dialog_content = "PlayerName, ¡No!",
  ui_story_5015_50150501_96_dialog_content = "Gretel ya no puede usar ese poder. ¡Su cuerpo no podrá soportarlo!",
  ui_story_5015_50150501_97_dialog_content = "Valencia, ¡cuidado! Urgh...",
  ui_story_5015_50150501_98_dialog_content = "Valencia... Siobhan...",
  ui_story_5015_50150501_99_dialog_content = "PlayerName, Dime qué hacer. ¡Haré lo que sea para salvar a mi hermana!",
  ui_story_5015_50150501_100_dialog_content = "Gretel, si uso poder psíquico contigo para activar tu poder...",
  ui_story_5015_50150501_101_dialog_content = "¡Lo haré!",
  ui_story_5015_50150501_102_dialog_content = "Está bien, definitivamente... haré mi mejor esfuerzo para no lastimarte.",
  ui_story_5015_50150501_103_option_content = "¡Establece un vínculo mental!",
  ui_story_5015_50150501_104_dialog_content = "Urgh, me... me duele... siento algo...",
  ui_story_5015_50150501_105_dialog_content = "Argh... yo... necesito... poder...",
  ui_story_5015_50150501_106_dialog_content = "¡¡¡Quiero proteger a Valencia ya todos los demás!!!",
  ui_story_5015_50150501_107_dialog_content = "¡Boom!",
  ui_story_5015_50150501_108_dialog_content = "Wow... que poderosa onda de choque...",
  ui_story_5015_50150501_109_dialog_content = "¡Ahora! Contraataque... ¡Ahora!",
  ui_story_5015_50150501_110_dialog_content = "<color=#e8d9bb>Mis predicciones se han superado. Este es el poder combinado de un Caelestite y un Aurorian...</color>",
  ui_story_5015_50150501_111_dialog_content = "<color=#e8d9bb>La energía liberada en ese ataque... es incluso mayor que la primera explosión explosiva de Gretel...</color>",
  ui_story_5015_50150501_112_dialog_content = "Esta es nuestra oportunidad de cambiar la situación. ¡Mata a todos los eclipses restantes de una sola vez!",
  ui_story_5015_50150501_113_dialog_content = "... Debo ganar... por Gretel.",
  ui_story_5015_50150501_114_dialog_content = "<color=#e8d9bb>¡Auge! ¡Bam!</color>",
  ui_story_5015_50150501_115_dialog_content = "Oh...",
  ui_story_5015_50150501_116_dialog_content = "H-hermana... ¿Ganamos... ganamos?",
  ui_story_5015_50150501_117_dialog_content = "¡Ganamos, Gretel! Matamos a todos los Eclipsites y droides aquí.",
  ui_story_5015_50150501_118_dialog_content = "¿Estás bien? ¿Te duele en alguna parte?",
  ui_story_5015_50150501_119_dialog_content = "Yo... estoy bien... Vamos con Abby para que el mayordomo pueda...",
  ui_story_5015_50150501_120_dialog_content = "Sí, lo sé. El Mayordomo y los demás ya han entrado... Te llevaré para allá ahora.",
  ui_story_5015_50150501_121_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_122_dialog_content = "Vicio, ¿qué está pasando? Dile a mi hermana ahora...",
  ui_story_5015_50150501_123_dialog_content = "El mayordomo se está conectando al centro de datos de Abby para intentar recuperar algo de autoridad.",
  ui_story_5015_50150501_124_dialog_content = "Mayordomo... ¿estás bien?",
  ui_story_5015_50150501_125_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_126_dialog_content = "Mayordomo... ¿Por qué... por qué no me contestas?",
  ui_story_5015_50150501_127_dialog_content = "Pequeña Gretel, está haciendo todo lo posible para conectarse al sistema de Abby. No te puede responder ahora...",
  ui_story_5015_50150501_128_dialog_content = "Oh, está bien... ¡Mayordomo, puedes hacerlo!",
  ui_story_5015_50150501_129_dialog_content = "Derrota a eso... Abby.",
  ui_story_5015_50150501_130_dialog_content = "Espera, este sentimiento... Se siente como cuando estaba conectado con el Mayordomo...",
  ui_story_5015_50150501_131_dialog_content = "Siento que puedo intervenir y tal vez incluso ver cómo está el Mayordomo...",
  ui_story_5015_50150501_132_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_133_dialog_content = "¿Mayordomo?",
  ui_story_5015_50150501_134_dialog_content = "... Mayordomo, ¿estás ahí?",
  ui_story_5015_50150501_135_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_136_dialog_content = "¡Mayordomo! ¿Cómo estás? ¿Funcionó? ¿Te conectaste con Abby...?",
  ui_story_5015_50150501_137_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_138_dialog_content = "Espera, tú no eres el Mayordomo. ¿Eres Abby?",
  ui_story_5015_50150501_139_dialog_content = "<color=#e8d9bb>PlayerName...</color>",
  ui_story_5015_50150501_140_dialog_content = "¡Oye! Q-que me estas haciendo... ¡¡Me duele la cabeza!!",
  ui_story_5015_50150501_141_dialog_content = "Mi conciencia está siendo desgarrada...",
  ui_story_5015_50150501_142_dialog_content = "<color=#e8d9bb>■■■■■</color>",
  ui_story_5015_50150501_143_dialog_content = "<color=#e8d9bb>■■■!!</color>",
  ui_story_5015_50150501_144_dialog_content = "<color=#e8d9bb>PlayerName, ¡peligro!</color>",
  ui_story_5015_50150501_145_dialog_content = "¡Mayordomo!",
  ui_story_5015_50150501_146_dialog_content = "<color=#e8d9bb>Te desviaste a la red de información en la que Abby y yo estamos. Eso fue muy peligroso...</color>",
  ui_story_5015_50150501_147_dialog_content = "<color=#e8d9bb>Afortunadamente, te descubrí a tiempo. Estás a salvo ahora que te estoy protegiendo.</color>",
  ui_story_5015_50150501_148_dialog_content = "¿Ya has... derrotado a Abby?",
  ui_story_5015_50150501_149_dialog_content = "<color=#e8d9bb>No, ella ya obtuvo la autoridad de los otros módulos, por lo que ahora es mucho más fuerte que yo.</color>",
  ui_story_5015_50150501_150_dialog_content = "<color=#e8d9bb>Según mis cálculos... Mis posibilidades de apoderarme de la autoridad son muy bajas.</color>",
  ui_story_5015_50150501_151_dialog_content = "<color=#e8d9bb>Abby también quiere usar esta conexión para apoderarse de mi autoridad.</color>",
  ui_story_5015_50150501_152_dialog_content = "¿Q-qué debemos hacer entonces...? ¿Hay algo que pueda hacer?",
  ui_story_5015_50150501_153_dialog_content = "<color=#e8d9bb>Lo siento... No puedes ayudarme.</color>",
  ui_story_5015_50150501_154_dialog_content = "¿Qué debemos hacer entonces? Tú... ¡No puedes perder! Si pierdes, todos moriremos...",
  ui_story_5015_50150501_155_dialog_content = "<color=#e8d9bb>Lo siento, PlayerName... Debes irte ahora.</color>",
  ui_story_5015_50150501_156_dialog_content = "<color=#e8d9bb>Mi pelea con Abby continuará aquí por un tiempo... No puedo predecir cuánto tiempo llevará porque el tiempo somatosensorial no tiene valor de referencia.</color>",
  ui_story_5015_50150501_157_dialog_content = "<color=#e8d9bb>No deberías esperar aquí...</color>",
  ui_story_5015_50150501_158_dialog_content = "<color=#e8d9bb>■■■■■!!</color>",
  ui_story_5015_50150501_159_dialog_content = "<color=#e8d9bb>... Ustedes...</color>",
  ui_story_5015_50150501_160_dialog_content = "<color=#e8d9bb>*golpe—golpe*</color>",
  ui_story_5015_50150501_161_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_162_dialog_content = "¿Qué es ese sonido? ¿Qué estás diciendo, mayordomo? No entiendo...",
  ui_story_5015_50150501_163_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_164_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■ ■■■■</color>",
  ui_story_5015_50150501_165_dialog_content = "<color=#e8d9bb>*golpe—golpe*</color>",
  ui_story_5015_50150501_166_dialog_content = "Mayordomo, ¿qué pasa?",
  ui_story_5015_50150501_167_dialog_content = "<color=#e8d9bb>No, soy Abby...</color>",
  ui_story_5015_50150501_168_dialog_content = "<color=#e8d9bb>■■■■■■■■■</color>",
  ui_story_5015_50150501_169_dialog_content = "M-me duele la cabeza... Abby... Mayordomo...",
  ui_story_5015_50150501_170_dialog_content = "<color=#e8d9bb>... Tú... ■■■■... deber...</color>",
  ui_story_5015_50150501_171_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■ mis ■■■■■■■■■■■■ residentes.</color>",
  ui_story_5015_50150501_172_dialog_content = "Las pantallas aquí... ¿Por qué parpadean todas?",
  ui_story_5015_50150501_173_dialog_content = "Debe ser porque actualmente el Mayordomo y Abby están peleando... Espero que todo salga bien.",
  ui_story_5015_50150501_174_dialog_content = "Si el Mayordomo pierde... Desaparecerá, y estaremos condenados seguro.",
  ui_story_5015_50150501_175_dialog_content = "No... ¡No quiero que el mayordomo muera! PlayerName! ¡Debes ayudar al mayordomo!",
  ui_story_5015_50150501_176_dialog_content = "¡¿No nos prometiste que ayudarías?!",
  ui_story_5015_50150501_177_dialog_content = "¡Deja de dormir! ... Dile al Mayordomo...",
  ui_story_5015_50150501_178_dialog_content = "Dile al Mayordomo... que debe ganar... Mi hermana y yo lo estamos esperando...",
  ui_story_5015_50150501_179_dialog_content = "<color=#e8d9bb>Peligro... ■■■■■■■■■■■</color>",
  ui_story_5015_50150501_180_dialog_content = "<color=#e8d9bb>■■■■■■!!</color>",
  ui_story_5015_50150501_181_dialog_content = "Mayordomo... ¿Qué pasa? ¡Esperar! ¡Este sentimiento es...! Mayordomo, ¿puedes oírme?",
  ui_story_5015_50150501_182_dialog_content = "<color=#e8d9bb>■■■■■ peligro ■■■■ peligro...</color>",
  ui_story_5015_50150501_183_dialog_content = "¡Es la voz de Gretel! ¿Puedes oír eso? ¡Es la voz de Gretel!",
  ui_story_5015_50150501_184_dialog_content = "Gre■■■■...",
  ui_story_5015_50150501_185_dialog_content = "¡¿No prometiste... que nos ayudarías?!",
  ui_story_5015_50150501_186_dialog_content = "Dile al Mayordomo... que debe ganar... Mi hermana y yo lo estamos esperando...",
  ui_story_5015_50150501_187_dialog_content = "Mayordomo... Por favor... no nos dejes...",
  ui_story_5015_50150501_188_dialog_content = "<color=#e8d9bb>■■■■■Gre■■■te■■■l■■■■...</color>",
  ui_story_5015_50150501_189_dialog_content = "Mayordomo... ¿Puedes oír eso? Gretel te necesita... Ella y su hermana te necesitan.",
  ui_story_5015_50150501_190_dialog_content = "<color=#e8d9bb>Detectado ■Gre■■■te■■■l■ Gretel■■■■</color>",
  ui_story_5015_50150501_191_dialog_content = "<color=#e8d9bb>¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡</color>",
  ui_story_5015_50150501_192_dialog_content = "<color=#e8d9bb>Peligro ■■■■■ Deja ■■■■■este lugar ■■■■■ ahora ■■■■■</color>",
  ui_story_5015_50150501_193_dialog_content = "¡Mayordomo!",
  ui_story_5015_50150501_194_dialog_content = "PlayerName, ¿estás bien? ¿Por qué te despertaste de repente?",
  ui_story_5015_50150501_195_dialog_content = "Yo... estoy bien, pero el Mayordomo...",
  ui_story_5015_50150501_196_dialog_content = "<color=#e8d9bb>Ruido sordo...</color>",
  ui_story_5015_50150501_197_dialog_content = "Huh, ¿qué fue ese destello?",
  ui_story_5015_50150501_198_dialog_content = "Oye, ¿algo brilló por un momento?",
  ui_story_5015_50150501_199_dialog_content = "Yo también lo vi. Parecía que venía del centro de datos...",
  ui_story_5015_50150501_200_dialog_content = "Se sentía como si algo hubiera estado allí antes, pero desapareció después de este momento.",
  ui_story_5015_50150501_201_dialog_content = "Oye, de repente me siento... vacío.",
  ui_story_5015_50150501_202_dialog_content = "No, puede que no sea una emoción. Abby no tiene emociones...",
  ui_story_5015_50150501_203_dialog_content = "Me siento vacío. Como... como si no quedara nada.",
  ui_story_5015_50150501_204_dialog_content = "Una conciencia... ha desaparecido. No sé si es Abby... o...",
  ui_story_5015_50150501_205_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_206_dialog_content = "<color=#e8d9bb>■■■■■■</color>",
  ui_story_5015_50150501_207_dialog_content = "Este... no parece el Mayordomo.",
  ui_story_5015_50150501_208_dialog_content = "¡Cuidado, todos!",
  ui_story_5015_50150501_209_dialog_content = "Espera, no parece muy estable.",
  ui_story_5015_50150501_210_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_211_dialog_content = "Mayordomo...? ¿Eres tu?",
  ui_story_5015_50150501_212_dialog_content = "<color=#e8d9bb>He obtenido con éxito todas... las autorizaciones.</color>",
  ui_story_5015_50150501_213_dialog_content = "<color=#e8d9bb>El módulo de Abby... ha dejado de funcionar.</color>",
  ui_story_5015_50150501_214_dialog_content = "Eso es genial... ¡El mayordomo ganó! ¡Esto es increíble!",
  ui_story_5015_50150501_215_dialog_content = "¡Hurra! ¡Estoy tan feliz! ¡El mayordomo realmente ganó!",
  ui_story_5015_50150501_216_dialog_content = "Mayordomo, ¿cómo lo lograste? ¿No dijiste que tus posibilidades de éxito eran muy bajas...?",
  ui_story_5015_50150501_217_dialog_content = "<color=#e8d9bb>En un momento, la posibilidad de éxito era casi nula.</color>",
  ui_story_5015_50150501_218_dialog_content = "<color=#e8d9bb>Pero en el instante el pensamiento: \"La residente, Gretel, quería que Butler derrotara a Abby\" apareció en la lógica del sistema de Abby,</color>",
  ui_story_5015_50150501_219_dialog_content = "<color=#e8d9bb>... en ese instante... tomé la delantera.</color>",
  ui_story_5015_50150501_220_dialog_content = "<color=#e8d9bb>PlayerName, tu conexión... introdujo nuevos datos...</color>",
  ui_story_5015_50150501_221_dialog_content = "<color=#e8d9bb>... en nuestro sistema... Gracias.</color>",
  ui_story_5015_50150501_222_dialog_content = "<color=#e8d9bb>Ahora he... obtenido todos los datos de Abby.</color>",
  ui_story_5015_50150501_223_dialog_content = "¿Qué encontraste? Por ejemplo, ¿por qué Abby modificó los eclipses?",
  ui_story_5015_50150501_224_dialog_content = "<color=#e8d9bb>Entiendo... todo lo que estaba pensando.</color>",
  ui_story_5015_50150501_225_dialog_content = "<color=#e8d9bb>Modificó los Eclipsites... porque había sido dañado...</color>",
  ui_story_5015_50150501_226_dialog_content = "<color=#e8d9bb>Abby a menudo no podía distinguir a los residentes de la ciudad... de los eclipses.</color>",
  ui_story_5015_50150501_227_dialog_content = "<color=#e8d9bb>En la mente de Abby... A veces pensaba que... estaba ayudando a los residentes a evolucionar.</color>",
  ui_story_5015_50150501_228_dialog_content = "<color=#e8d9bb>A veces era consciente... de que no eran residentes... y que eran otro tipo de forma de vida desconocida.</color>",
  ui_story_5015_50150501_229_dialog_content = "<color=#e8d9bb>Se dio cuenta de que las criaturas que modificaba... tenían fuertes impulsos agresivos.</color>",
  ui_story_5015_50150501_230_dialog_content = "<color=#e8d9bb>Para proteger a los residentes de la ciudad... a pesar de que ya... han desaparecido...</color>",
  ui_story_5015_50150501_231_dialog_content = "<color=#e8d9bb>Abby todavía implantó instrucciones para evitar que los residentes de la ciudad entraran en los genes de los Eclipsites.</color>",
  ui_story_5015_50150501_232_dialog_content = "Ya veo, así es como funciona el estatus de residente de Gretel...",
  ui_story_5015_50150501_233_dialog_content = "Entonces, ¿por qué los Eclipsites comenzaron a atacar a Gretel más tarde?",
  ui_story_5015_50150501_234_dialog_content = "<color=#e8d9bb>Abby pensó que... tus acciones representaban una amenaza para la existencia continua de la ciudad... incluida Gretel.</color>",
  ui_story_5015_50150501_235_dialog_content = "Apenas rompemos nada... ¿Cómo nos convertimos en una amenaza?",
  ui_story_5015_50150501_236_dialog_content = "Uh... Incluso si golpeamos o rompimos algo, fue porque no teníamos otra opción.",
  ui_story_5015_50150501_237_dialog_content = "Ruby, no diría apenas...",
  ui_story_5015_50150501_238_dialog_content = "Ejem... ese no es el punto.",
  ui_story_5015_50150501_239_dialog_content = "<color=#e8d9bb>Es porque me ayudaste... lo que le dificultó obtener las autorizaciones que necesitaba para reparar las estrellas de Alchemy.</color>",
  ui_story_5015_50150501_240_dialog_content = "<color=#e8d9bb>La inestabilidad de las estrellas de la Alquimia... podría resultar en la destrucción de la ciudad.</color>",
  ui_story_5015_50150501_241_dialog_content = "Pero reparar las estrellas de Alchemy suena más como tu responsabilidad.",
  ui_story_5015_50150501_242_dialog_content = "¿No eres el mayordomo?",
  ui_story_5015_50150501_243_dialog_content = "<color=#e8d9bb>Abby... necesita mantener el ambiente en la ciudad.</color>",
  ui_story_5015_50150501_244_dialog_content = "<color=#e8d9bb>Por lo tanto... eligió lograr su objetivo reparando las estrellas de Alquimia.</color>",
  ui_story_5015_50150501_245_dialog_content = "Mayordomo, ya que ha adquirido todas las autorizaciones, ¿puede verificar la situación actual de las estrellas de Alchemy?",
  ui_story_5015_50150501_246_dialog_content = "¡Correcto! ¡Revíselo ahora!",
  ui_story_5015_50150501_247_dialog_content = "<color=#e8d9bb>Iniciando una inspección de las estrellas de Alchemy.</color>",
  ui_story_5015_50150501_248_dialog_content = "<color=#e8d9bb>... Inventario de energía... Aprobado...</color>",
  ui_story_5015_50150501_249_dialog_content = "<color=#e8d9bb>... Integridad del oleoducto... 23% dañado...</color>",
  ui_story_5015_50150501_250_dialog_content = "<color=#e8d9bb>... Prueba de estabilidad... Falló...</color>",
  ui_story_5015_50150501_251_dialog_content = "<color=#e8d9bb>... Activando el programa de reparación...</color>",
  ui_story_5015_50150501_252_dialog_content = "<color=#e8d9bb>¡Error! ¡Error! Falta el programa de reparación. ¡Activación fallida!</color>",
  ui_story_5015_50150501_253_dialog_content = "Mayordomo, ¿qué pasó?",
  ui_story_5015_50150501_254_dialog_content = "<color=#e8d9bb>He realizado una inspección... Hay un... programa de reparación en los datos de Abby.</color>",
  ui_story_5015_50150501_255_dialog_content = "<color=#e8d9bb>Según la información... Este programa de reparación es el único método de reparación existente.</color>",
  ui_story_5015_50150501_256_dialog_content = "<color=#e8d9bb>Pero se ha dañado... hasta el punto de que no se puede ejecutar.</color>",
  ui_story_5015_50150501_257_dialog_content = "<color=#e8d9bb>Aun así, Abby trató de ejecutar a la fuerza el... programa de reparación... lo que provocó que las estrellas de Alchemy sufrieran daños irreversibles.</color>",
  ui_story_5015_50150501_258_dialog_content = "Con razón hubo tantos terremotos cuando Abby estaba reparando el núcleo de energía...",
  ui_story_5015_50150501_259_dialog_content = "Y pensé que nuestras batallas habían afectado el núcleo de energía.",
  ui_story_5015_50150501_260_dialog_content = "¿Cuál es la situación de las estrellas de Alchemy ahora?",
  ui_story_5015_50150501_261_dialog_content = "<color=#e8d9bb>Según mis cálculos, las estrellas de Alchemy ya no se pueden reparar... Se volverán menos estables con el tiempo.</color>",
  ui_story_5015_50150501_262_dialog_content = "<color=#e8d9bb>Todas las operaciones de alta autoridad... aumentarán la carga colocada en las estrellas de Alquimia.</color>",
  ui_story_5015_50150501_263_dialog_content = "<color=#e8d9bb>Cuando las operaciones... alcancen su punto máximo, podría conducir a un extremadamente poderoso...</color>",
  ui_story_5015_50150501_264_dialog_content = "<size=45><color=#FFB400>... explosión.</color></size>",
  ui_story_5015_50150601_1_dialog_content = "¿Eh? ¿Quieres decir que las estrellas de Alchemy no se pueden reparar?",
  ui_story_5015_50150601_2_dialog_content = "¡Entonces tenemos que irnos ahora!",
  ui_story_5015_50150601_3_dialog_content = "Pero... Mayordomo, ¿nos dirás cómo salir?",
  ui_story_5015_50150601_4_dialog_content = "Sí, ¿abrirás el camino para que nos vayamos?",
  ui_story_5015_50150601_5_dialog_content = "Después de todo, esto es algo que pone en peligro la seguridad de la ciudad.",
  ui_story_5015_50150601_6_dialog_content = "Gretel, ¿puedes preguntarle al mayordomo por nosotros?",
  ui_story_5015_50150601_7_dialog_content = "Pídele que nos deje esta ciudad subterránea...",
  ui_story_5015_50150601_8_dialog_content = "¡No me iré!",
  ui_story_5015_50150601_9_dialog_content = "¡Valencia, quiero quedarme aquí con el Mayordomo!",
  ui_story_5015_50150601_10_dialog_content = "Gretel, ¿qué es esta tontería?",
  ui_story_5015_50150601_11_dialog_content = "¿No oíste lo que dijo el Mayordomo? ¡Esta ciudad subterránea podría volar por los aires!",
  ui_story_5015_50150601_12_dialog_content = "¿No eran ya inestables las estrellas de Alchemy cuando mamá y papá aún vivían?",
  ui_story_5015_50150601_13_dialog_content = "Pero seguimos viviendo aquí durante la última década o más... y nada explotó.",
  ui_story_5015_50150601_14_dialog_content = "Tal vez las estrellas de Alchemy aún puedan continuar durante mucho tiempo, incluso si son inestables...",
  ui_story_5015_50150601_15_dialog_content = "Valencia, te lo ruego... ¡Por favor, déjame quedarme! No quiero salir.",
  ui_story_5015_50150601_16_dialog_content = "¡Gretel, no es el momento de ser testaruda! ¡No es tan aterrador como piensas por ahí!",
  ui_story_5015_50150601_17_dialog_content = "Siempre estaré contigo también.",
  ui_story_5015_50150601_18_dialog_content = "Todos estarán contigo también... Illumina también cuidará de nosotros...",
  ui_story_5015_50150601_19_dialog_content = "Valencia tiene razón. Illumina definitivamente cuidará de ustedes ya que son los hijos de Seamus.",
  ui_story_5015_50150601_20_dialog_content = "La Iglesia de la Lumopolis también te albergará por el bien de tu madre.",
  ui_story_5015_50150601_21_dialog_content = "¡Por supuesto, puedes venir a nosotros si quieres jugar en el desierto de Rediesel!",
  ui_story_5015_50150601_22_dialog_content = "Podemos discutir los detalles más tarde. ¡Lo más importante es salir de aquí con vida!",
  ui_story_5015_50150601_23_dialog_content = "Pero... el Mayordomo... Dijo que no podemos...",
  ui_story_5015_50150601_24_dialog_content = "<color=#e8d9bb>La situación ha cambiado... Gretel, te sugiero que... te vayas.</color>",
  ui_story_5015_50150601_25_dialog_content = "<color=#e8d9bb>Todos, les abriré una salida.</color>",
  ui_story_5015_50150601_26_dialog_content = "<color=#e8d9bb>Abrir una salida es una operación de alta autoridad... por lo que el núcleo de energía podría explotar poco después.</color>",
  ui_story_5015_50150601_27_dialog_content = "<color=#e8d9bb>Te sugiero que vayas rápido... después de que se abriera la salida.</color>",
  ui_story_5015_50150601_28_dialog_content = "Mayordomo, ¿realmente estás dispuesto a sacrificar esta ciudad solo para dejarnos irnos?",
  ui_story_5015_50150601_29_dialog_content = "<color=#e8d9bb>La ciudad ya no es... apta para vivir... No hay esperanza para este lugar...</color>",
  ui_story_5015_50150601_30_dialog_content = "<color=#e8d9bb>Recordar...</color>",
  ui_story_5015_50150601_31_dialog_content = "<color=#e8d9bb>Abrir una salida... es una operación de alta autoridad.</color>",
  ui_story_5015_50150601_32_dialog_content = "<color=#e8d9bb>Aumentará significativamente la carga en las estrellas de Alquimia.</color>",
  ui_story_5015_50150601_33_dialog_content = "<color=#e8d9bb>Incluso podría... desencadenar explosiones.</color>",
  ui_story_5015_50150601_34_dialog_content = "<color=#e8d9bb>Por favor ve... a estas coordenadas y espera... para que puedas salir inmediatamente cuando sea el momento.</color>",
  ui_story_5015_50150601_35_dialog_content = "¡No! ¡Quiero que el Mayordomo... se vaya con nosotros! *Sollozo*",
  ui_story_5015_50150601_36_dialog_content = "Mayordomo, puedes irte con nosotros, ¿verdad?",
  ui_story_5015_50150601_37_dialog_content = "<color=#e8d9bb>Lo siento, Gretel... Mi centro de datos está aquí. No me puedo ir.</color>",
  ui_story_5015_50150601_38_dialog_content = "<color=#e8d9bb>Necesito quedarme... para abrirte la salida.</color>",
  ui_story_5015_50150601_39_dialog_content = "Entonces yo también me quedo...",
  ui_story_5015_50150601_40_dialog_content = "Gretel, escúchame. Podemos volver después de irnos.",
  ui_story_5015_50150601_41_dialog_content = "El mayordomo no dijo que abrir una salida definitivamente desencadenaría la explosión.",
  ui_story_5015_50150601_42_dialog_content = "Guardaré las coordenadas de la ciudad subterránea para que el equipo de expedición de Illumina pueda encontrar este lugar y excavar la ciudad subterránea después de que nos vayamos.",
  ui_story_5015_50150601_43_dialog_content = "Entonces podrás reunirte con el Mayordomo. ¿No sería eso bueno?",
  ui_story_5015_50150601_44_dialog_content = "No me estás mintiendo... ¿verdad?",
  ui_story_5015_50150601_45_dialog_content = "Te lo prometo, les instaré a que actúen rápidamente después de que salgamos.",
  ui_story_5015_50150601_46_dialog_content = "*Sollozo* Mayordomo... espéranos a salvo aquí... hasta que volvamos.",
  ui_story_5015_50150601_47_dialog_content = "<color=#e8d9bb>Gretel, todos, prepárense ahora... Prepárense para partir.</color>",
  ui_story_5015_50150601_48_dialog_content = "¿Hay algo más que alguien deba hacer primero?",
  ui_story_5015_50150601_49_dialog_content = "Vice, ¿almacenaste los datos de investigación de Seamus?",
  ui_story_5015_50150601_50_dialog_content = "¡Puede confiar en mí con eso, señorita Siobhan!",
  ui_story_5015_50150601_51_dialog_content = "¿Necesitamos copiar más datos del centro de datos antes de irnos?",
  ui_story_5015_50150601_52_dialog_content = "Todavía quieres hacer eso en un momento como este... ¿No tienes miedo de crear más problemas?",
  ui_story_5015_50150601_53_dialog_content = "Olvídalo, Vice... Escapar es más importante ahora.",
  ui_story_5015_50150601_54_dialog_content = "Lo más importante es asegurarse de que todos estén a salvo... Gretel y Valencia son nuestro mayor hallazgo de esta expedición.",
  ui_story_5015_50150601_55_dialog_content = "Uf... finalmente puedo volver a cambiarme de ropa.",
  ui_story_5015_50150601_56_dialog_content = "¿Es aquí donde el mayordomo dijo que está la salida?",
  ui_story_5015_50150601_57_dialog_content = "Correcto.",
  ui_story_5015_50150601_58_dialog_content = "Pero PlayerName... Gretel parece bastante deprimida.",
  ui_story_5015_50150601_59_dialog_content = "Entiendo cómo se siente.",
  ui_story_5015_50150601_60_dialog_content = "Para ella, el mayordomo es un amigo cercano, incluso un miembro de su familia.",
  ui_story_5015_50150601_61_dialog_content = "Al igual que yo y Soroz.",
  ui_story_5015_50150601_62_dialog_content = "Quiero decir... no tienen otra opción que estar separados en esta situación.",
  ui_story_5015_50150601_63_dialog_content = "Oh...",
  ui_story_5015_50150601_64_dialog_content = "¿Qué es?",
  ui_story_5015_50150601_65_dialog_content = "Yo... de repente me siento un poco mareado...",
  ui_story_5015_50150601_66_dialog_content = "Podría ser... Oye, PlayerName...",
  ui_story_5015_50150601_67_dialog_content = "¡Oye! Despierta... Que te pasa... Oye...",
  ui_story_5015_50150601_68_dialog_content = "<color=#e8d9bb>Hola... PlayerName, ¿puedes escucharme?</color>",
  ui_story_5015_50150601_69_dialog_content = "¿Hemos vuelto a establecer una conexión telepática?",
  ui_story_5015_50150601_70_dialog_content = "¿Cómo van las cosas, mayordomo? ¿Está abierta la salida?",
  ui_story_5015_50150601_71_dialog_content = "¿Por qué podemos de repente...",
  ui_story_5015_50150601_72_dialog_content = "<color=#e8d9bb>He obtenido todas las autorizaciones de esta ciudad, así que puedo conectarme contigo en cualquier momento.</color>",
  ui_story_5015_50150601_73_dialog_content = "¿No nos estás abriendo la salida...?",
  ui_story_5015_50150601_74_dialog_content = "<color=#e8d9bb>Ya he ejecutado los procedimientos para abrir la salida y todavía se está cargando.</color>",
  ui_story_5015_50150601_75_dialog_content = "<color=#e8d9bb>Podrás salir en 3 minutos.</color>",
  ui_story_5015_50150601_76_dialog_content = "... Hablando honestamente, todavía estoy sorprendido de que hayas accedido a abrirnos la salida.",
  ui_story_5015_50150601_77_dialog_content = "Seguiste enfatizando que tu principal prioridad es mantener la ciudad segura y dijiste que no tenías emociones.",
  ui_story_5015_50150601_78_dialog_content = "Pensé que nos obligarías a permanecer bajo tierra por la seguridad de la ciudad.",
  ui_story_5015_50150601_79_dialog_content = "<color=#e8d9bb>Protegí la ciudad para mantener viva nuestra civilización.</color>",
  ui_story_5015_50150601_80_dialog_content = "<color=#e8d9bb>Ya que todos los residentes se han ido... Todo este metal, concreto, polvo e incluso nosotros ahora son inútiles.</color>",
  ui_story_5015_50150601_81_dialog_content = "<color=#e8d9bb>Según mis cálculos, mantenerte aquí y hacerte enfrentar los terremotos, los eclipses y la fuente de energía inestable...</color>",
  ui_story_5015_50150601_82_dialog_content = "<color=#e8d9bb>... no me ayuda a completar mi misión.</color>",
  ui_story_5015_50150601_83_dialog_content = "<color=#e8d9bb>Por lo tanto, destruirme para enviarte lejos está completamente en línea con mi programa.</color>",
  ui_story_5015_50150601_84_dialog_content = "<color=#e8d9bb>Al final, es una pena que no hayamos podido proteger a los residentes originales de la ciudad.</color>",
  ui_story_5015_50150601_85_dialog_content = "No.",
  ui_story_5015_50150601_86_dialog_content = "Incluso si los residentes anteriores ahora están perdidos en la historia...",
  ui_story_5015_50150601_87_dialog_content = "Su espíritu vive en ti...",
  ui_story_5015_50150601_88_dialog_content = "Tus decisiones y perseverancia han entregado sus creencias.",
  ui_story_5015_50150601_89_dialog_content = "Has conectado con nosotros después de tanto tiempo y nos lo has transmitido todo.",
  ui_story_5015_50150601_90_dialog_content = "No deberías tener ningún remordimiento.",
  ui_story_5015_50150601_91_dialog_content = "<color=#e8d9bb>Me alegra que reconozcas todo lo que he hecho.</color>",
  ui_story_5015_50150601_92_dialog_content = "<color=#e8d9bb>Pero todavía tengo algunos remordimientos.</color>",
  ui_story_5015_50150601_93_dialog_content = "<color=#e8d9bb>Nosotros... finalmente le dimos la bienvenida a un nuevo residente, Gretel.</color>",
  ui_story_5015_50150601_94_dialog_content = "<color=#e8d9bb>Pero no puedo acompañar a Gretel para siempre como ella quiere que lo haga.</color>",
  ui_story_5015_50150601_95_dialog_content = "<color=#e8d9bb>Quiero que le transmita mis disculpas.</color>",
  ui_story_5015_50150601_96_dialog_content = "Para ser honesto, cuando se trata de este tipo de cosas...",
  ui_story_5015_50150601_97_dialog_content = "Estás actuando... como un organismo vivo que piensa y tiene emociones.",
  ui_story_5015_50150601_98_dialog_content = "Una máquina no se sentiría apenada o arrepentida, ¿verdad?",
  ui_story_5015_50150601_99_dialog_content = "<color=#e8d9bb>Tal vez así fue como fui diseñado en primer lugar.</color>",
  ui_story_5015_50150601_100_dialog_content = "<color=#e8d9bb>Mi diseño hace que parezca que tengo un lado humano para que sea más fácil comunicarme contigo.</color>",
  ui_story_5015_50150601_101_dialog_content = "Pero en este momento, tengo un sentimiento tan fuerte... que tienes sentimientos.",
  ui_story_5015_50150601_102_dialog_content = "Dime, ¿cómo definimos si alguien o algo \"tiene sentimientos\"?",
  ui_story_5015_50150601_103_dialog_content = "<color=#e8d9bb>... Estruendo...</color>",
  ui_story_5015_50150601_104_dialog_content = "¿Qué es ese sonido?",
  ui_story_5015_50150601_105_dialog_content = "<color=#e8d9bb>Lo siento, no puedo responder a su pregunta... La salida se ha abierto y es hora de despedirnos.</color>",
  ui_story_5015_50150601_106_dialog_content = "<color=#e8d9bb>Supongo que no es apropiado terminar con hasta luego, ya que esta es realmente nuestra última despedida.</color>",
  ui_story_5015_50150601_107_dialog_content = "<color=#e8d9bb>Deseo que todos ustedes lleguen a la superficie a salvo.</color>",
  ui_story_5015_50150601_108_dialog_content = "... Mayordomo...",
  ui_story_5015_50150601_109_dialog_content = "PlayerName, ¡despierta ahora! ¡La salida está abierta!",
  ui_story_5015_50150601_110_dialog_content = "¿Tuviste una conexión con el mayordomo otra vez?",
  ui_story_5015_50150601_111_dialog_content = "Sí... Oh cierto, tengo algo que decirle a Gretel...",
  ui_story_5015_50150601_112_dialog_content = "*Sollozo* Hermana, no quiero irme.",
  ui_story_5015_50150601_113_dialog_content = "Quiero volver con el Mayordomo...",
  ui_story_5015_50150601_114_dialog_content = "Gretel... Toma mi mano fuerte porque es hora de irnos.",
  ui_story_5015_50150601_115_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5015_50150601_116_dialog_content = "¿Es otro terremoto?",
  ui_story_5015_50150601_117_dialog_content = "Estamos fuera de tiempo... PlayerName¡Gretel, tenemos que irnos ahora!",
  ui_story_5015_50150601_118_dialog_content = "¡Gretel, vamos!",
  ui_story_5015_50150601_119_dialog_content = "*Sollozo* Mayordomo...",
  ui_story_5015_50150601_120_dialog_content = "PlayerName, cuidado con los objetos que caen!",
  ui_story_5015_50150601_121_dialog_content = "... Uf, eso estuvo cerca. ¡Cuidado con las rocas que caen!",
  ui_story_5015_50150601_122_dialog_content = "¿Llegaremos a tiempo si subimos así?",
  ui_story_5015_50150601_123_dialog_content = "¿Y si este lugar realmente explota como dijo el mayordomo?",
  ui_story_5015_50150601_124_dialog_content = "Realmente espero que Soroz pueda recogernos.",
  ui_story_5015_50150601_125_dialog_content = "Incluso una aeronave serviría... Solo necesitamos algo que pueda volar directamente.",
  ui_story_5015_50150601_126_dialog_content = "Ruby, tu imaginación es tan poco realista.",
  ui_story_5015_50150601_127_dialog_content = "Al menos el Coloso está cerca... ¿Sabes a qué distancia está una aeronave? No es posible.",
  ui_story_5015_50150601_128_dialog_content = "¿Un dirigible?",
  ui_story_5015_50150601_129_dialog_content = "Princesa Carleen, ¿nunca has visto una aeronave a pesar de que vives en Lumopolis?",
  ui_story_5015_50150601_130_dialog_content = "No, de repente recordé que realmente tenemos algo que puede volar...",
  ui_story_5015_50150601_131_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5015_50150601_132_dialog_content = "¿Es eso... el sonido de una explosión?",
  ui_story_5015_50150601_133_dialog_content = "¿Podrían las estrellas de Alchemy ya...",
  ui_story_5015_50150601_134_dialog_content = "¡¡¡Mayordomo!!! *Sollozo*",
  ui_story_5015_50150601_135_dialog_content = "¡Rápido! ¡Sube y no te sueltes! Gretel, te levantaré...",
  ui_story_5015_50150601_136_dialog_content = "¡Muévanse rápido, todos! ¡Tenemos que dejar los niveles inferiores! Las explosiones han comenzado.",
  ui_story_5015_50150601_137_dialog_content = "Todavía estamos a varios cientos de metros de la superficie. Puede que no logremos salir antes de que nos alcancen las explosiones...",
  ui_story_5015_50150601_138_dialog_content = "Cuidado con las rocas... ¡El derrumbe es cada vez peor!",
  ui_story_5015_50150601_139_dialog_content = "Esto no funcionará. ¡Necesitamos una forma rápida de llegar a la superficie!",
  ui_story_5015_50150601_140_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5015_50150601_141_dialog_content = "Oh no... ¡el pasaje se ha resquebrajado!",
  ui_story_5015_50150601_142_dialog_content = "¡Y la grieta es demasiado grande! Mira la ciudad afuera...",
  ui_story_5015_50150601_143_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5015_50150601_144_dialog_content = "¡Sube más rápido!",
  ui_story_5015_50150601_145_dialog_content = "La superficie sigue estando bien... Solo nos falta subir al ascensor...",
  ui_story_5015_50150601_146_dialog_content = "No... no podemos levantarnos. ¡La parte del medio se ha roto!",
  ui_story_5015_50150601_147_dialog_content = "<color=#e8d9bb>¡Boooom!</color>",
  ui_story_5015_50150601_148_dialog_content = "Incluso esta sección del pasaje se está derrumbando... ¡Estamos condenados!",
  ui_story_5015_50150601_149_dialog_content = "¡¡¡Sal ahora!!!",
  ui_story_5015_50150601_150_dialog_content = "¿Qué? ¿Es eso un... caballo? ¿Puedes convocar a un caballo con Luminatics?",
  ui_story_5015_50150601_151_dialog_content = "¡Todos, súbanse ahora!",
  ui_story_5015_50150601_152_dialog_content = "PlayerName¡Vicio, toma mi mano!",
  ui_story_5015_50150601_153_dialog_content = "Huff... ya voy... arriba...",
  ui_story_5015_50150601_154_dialog_content = "No, señorita Siobhan, mis pantalones están a punto de romperse...",
  ui_story_5015_50150601_155_dialog_content = "Pero estamos en el aire. Estaré condenado si no me agarro con fuerza.",
  ui_story_5015_50150601_156_dialog_content = "¡Todos debajo de mí también estarán condenados!",
  ui_story_5015_50150601_157_dialog_content = "¡Vaya, has formado un rastro tan largo!",
  ui_story_5015_50150601_158_dialog_content = "No esperaba que pudiéramos volar en el aire así...",
  ui_story_5015_50150601_159_dialog_content = "Carleen, ¿podemos volver al pasaje en la superficie?",
  ui_story_5015_50150601_160_dialog_content = "¡Podemos! Los terremotos y las explosiones han ensanchado la salida...",
  ui_story_5015_50150601_161_dialog_content = "¡Podemos volar directamente!",
  ui_story_5015_50150601_162_dialog_content = "¡Rouge, esta sí que es una experiencia de vuelo de 5 estrellas!",
  ui_story_5015_50150601_163_dialog_content = "¡Es simplemente demasiado emocionante!",
  ui_story_5015_50150601_164_dialog_content = "¿No puedes reducir las bromas ahora mismo? ¿Puedes actuar más en serio?",
  ui_story_5015_50150601_165_dialog_content = "Suspiro, quién hubiera esperado que nos fuéramos así...",
  ui_story_5015_50150601_166_dialog_content = "Así, una hermosa ciudad tiene...",
  ui_story_5015_50150601_167_dialog_content = "... Volado en pedazos.",
  ui_story_5015_50150601_168_dialog_content = "¡Uf! Gracias a Dios salimos vivos.",
  ui_story_5015_50150601_169_dialog_content = "Hagamos un recuento.",
  ui_story_5015_50150601_170_dialog_content = "¿Alguien resultó herido?",
  ui_story_5015_50150601_171_dialog_content = "Todos se levantaron a salvo.",
  ui_story_5015_50150601_172_dialog_content = "Correcto, PlayerName, Yo, Vice, Valencia y Gretel tenemos que informar a Illumina...",
  ui_story_5015_50150601_173_dialog_content = "¿Por qué deben seguirte de regreso a Illumina?",
  ui_story_5015_50150601_174_dialog_content = "Nimbus claramente los confió a la Iglesia de Lumopolis.",
  ui_story_5015_50150601_175_dialog_content = "Eso fue si nadie de Illumina estaba allí.",
  ui_story_5015_50150601_176_dialog_content = "Siobhan, eres tan dominante...",
  ui_story_5015_50150601_177_dialog_content = "¡Ustedes! ¿No es la mejor solución preguntarle a Valencia y Gretel adónde quieren ir?",
  ui_story_5015_50150601_178_dialog_content = "Gretel...",
  ui_story_5015_50150601_179_dialog_content = "*sollozo* hermana...",
  ui_story_5015_50150601_180_dialog_content = "Esto no es real... ¿verdad?",
  ui_story_5015_50150601_181_dialog_content = "¿Estoy soñando? Dime que esto es una pesadilla... *Sollozo*",
  ui_story_5015_50150601_182_dialog_content = "Despiértame ahora... ¿Puedes pedirle al mayordomo que me despierte...?",
  ui_story_5015_50150601_183_dialog_content = "Todavía tengo que ir a la escuela con el Ángel de la Guarda No. 3... Dijimos que iríamos a dar un paseo juntos...",
  ui_story_5015_50150601_184_dialog_content = "Íbamos a ver quién terminaba primero una vuelta al parque central...",
  ui_story_5015_50150601_185_dialog_content = "El Mayordomo me dijo que encontró una nueva receta que incluso tú puedes hacer fácilmente, hermana...",
  ui_story_5015_50150601_186_dialog_content = "Hicimos un trato para ir a pescar, y todavía tenemos que limpiar la habitación de mamá y papá como siempre...",
  ui_story_5015_50150601_187_dialog_content = "Está tan desordenado allí ahora... porque los datos están en todas partes... Estoy seguro de que estarán contentos después de que los limpie.",
  ui_story_5015_50150601_188_dialog_content = "Gretel... la ciudad ya está...",
  ui_story_5015_50150601_189_dialog_content = "*Sollozo* Sería bueno si esto fuera una pesadilla...",
  ui_story_5015_50150601_190_dialog_content = "¿Por qué? ¿Por qué sucedió esto?",
  ui_story_5015_50150601_191_dialog_content = "... El mayordomo... ¿preparó una nueva receta?",
  ui_story_5015_50150601_192_dialog_content = "Sí... los ingredientes son el pescado que pescamos... y las plantas que encontramos la última vez...",
  ui_story_5015_50150601_193_dialog_content = "Debe haber sido difícil... Hay tantos ingredientes comestibles... sin embargo, siguió pensando en formas de diseñar diferentes comidas para nosotros.",
  ui_story_5015_50150601_194_dialog_content = "Espero que podamos comer mejor comida aquí. . .",
  ui_story_5015_50150601_195_dialog_content = "Estoy seguro de que el mayordomo estará feliz de saber que comerás a tiempo todos los días y que ya no serás quisquilloso con la comida...",
  ui_story_5015_50150601_196_dialog_content = "*Sollozo* Yo... ya no seré quisquilloso con la comida...",
  ui_story_5015_50150601_197_dialog_content = "Tengo muchas ganas de que el Mayordomo esté aquí con nosotros...",
  ui_story_5015_50150601_198_dialog_content = "Hubiera sido genial si el Mayordomo fuera una persona... Entonces podría haberse ido con nosotros...",
  ui_story_5015_50150601_199_dialog_content = "Podría estar aquí con nosotros...",
  ui_story_5015_50150601_200_dialog_content = "Gretel, todavía me tienes. Siempre estaré aquí para ti...",
  ui_story_5015_50150601_201_dialog_content = "Boo-hoo...",
  ui_story_5015_50150601_202_dialog_content = "Me pregunto... qué pensarían mamá y papá si supieran que volvimos al mundo en el que solían vivir.",
  ui_story_5015_50150601_203_dialog_content = "Conocimos a sus compañeros del pasado y sobrevivimos juntos a una crisis.",
  ui_story_5015_50150601_204_dialog_content = "Me protegí el uno al otro. Finalmente reunimos el coraje para venir a esta tierra real.",
  ui_story_5015_50150601_205_dialog_content = "Podemos mirar... el cielo real.",
  ui_story_5015_50150601_206_dialog_content = "¿Qué pasa con las guerras? ¿Todavía hay guerras?",
  ui_story_5015_50150601_207_dialog_content = "¿Hay también muchos eclipses aquí?",
  ui_story_5015_50150601_208_dialog_content = "Eso no importa porque seguiremos juntos, Gretel.",
  ui_story_5015_50150601_209_dialog_content = "Hermana...",
  ui_story_5015_50150601_210_dialog_content = "Nos encontraré un nuevo hogar. Confía en mí.",
  ui_story_5015_50150601_211_dialog_content = "Mientras estemos juntos, cualquier lugar puede ser nuestro hogar.",
  ui_story_5015_50150601_212_dialog_content = "... Mientras esté con mi hermana... entonces tengo un hogar...",
  ui_story_5015_50150601_213_dialog_content = "(Parece que Gretel se ha calmado...)",
  ui_story_5015_50150601_214_dialog_content = "(Es posible que no todo haya sido destruido... Todavía tenemos las coordenadas y la información, por lo que Illumina aún puede excavarlo).",
  ui_story_5015_50150601_215_dialog_content = "(Pero no puedo decir eso directamente en este momento).",
  ui_story_5015_50150601_216_dialog_content = "(O bien Gretel podría hacer algo impulsivo. Sin mencionar que Florine y los demás están aquí...)",
  ui_story_5015_50150601_217_dialog_content = "¿Qué está pensando, señorita Siobhan?",
  ui_story_5015_50150601_218_dialog_content = "Ejem, nada. Preguntemos a Valencia y Gretel cuáles son sus planes para el futuro.",
  ui_story_5015_50150601_219_dialog_content = "Valencia, Gretel, ¿quieres ir a Umbraton? Puedo mostrarte el lugar.",
  ui_story_5015_50150601_220_dialog_content = "Tal vez... Todavía no me he decidido, así que puedo seguirte por un tiempo.",
  ui_story_5015_50150601_221_dialog_content = "Quiero decir, ahora es nuestro turno de ser extraños...",
  ui_story_5015_50150601_222_dialog_content = "Correcto, Ruby, ¿tenemos dinero?",
  ui_story_5015_50150601_223_dialog_content = "Tendremos que comprarles algunas cosas después de que lleguemos allí...",
  ui_story_5015_50150601_224_dialog_content = "Florine y yo podemos...",
  ui_story_5015_50150601_225_dialog_content = "Oh, también tenemos nuestras propias intenciones... ¿Crees que debemos preocuparnos por el dinero? ¡Mirar!",
  ui_story_5015_50150601_226_dialog_content = "Yo... ¿estoy alucinando?",
  ui_story_5015_50150601_227_dialog_content = "Ya puedes dejar de frotarte los ojos. Todo esto es real.",
  ui_story_5015_50150601_228_dialog_content = "Recogí todo esto mientras nos íbamos...",
  ui_story_5015_50150601_229_dialog_content = "Piezas de droides, latas, componentes de herramientas... ¡y atuendos antiguos!",
  ui_story_5015_50150601_230_dialog_content = "¡Podemos venderlos por mucho dinero en Umbraton!",
  ui_story_5015_50150601_231_dialog_content = "¡Rouge, vamos a ser ricos!",
  ui_story_5015_50150601_232_dialog_content = "Ruby, ¿cómo puedes decir eso en un momento como este...",
  ui_story_5015_50150601_233_dialog_content = "Ejem, Valencia, Gretel, de hecho tomé todo esto por ti.",
  ui_story_5015_50150601_234_dialog_content = "¡Sí! Estos te pertenecían. ¿Quieres guardar algunos de ellos como recuerdos?",
  ui_story_5015_50150601_235_dialog_content = "Lo que Ruby quiere decir es que todas las cosas aquí son tuyas...",
  ui_story_5015_50150601_236_dialog_content = "... Deja de explicar... ¿Crees que no entiendo?",
  ui_story_5015_50150601_237_dialog_content = "Tomaremos esta ropa. Puedes quedarte con el resto...",
  ui_story_5015_50150601_238_dialog_content = "¡Uf... eso es genial! ¡Eres bastante generoso!",
  ui_story_5015_50150601_239_dialog_content = "...",
  ui_story_5015_50150601_240_dialog_content = "Valencia, Gretel, ¿quieres tomar la sugerencia de Rouge e ir a Umbraton?",
  ui_story_5015_50150601_241_dialog_content = "Gretel, ¿qué dices? ¿Adónde quieres ir primero?",
  ui_story_5015_50150601_242_dialog_content = "Soy feliz mientras esté contigo, hermana...",
  ui_story_5015_50150601_243_dialog_content = "Oh cierto, Gretel. No pude transmitirles el mensaje del mayordomo antes debido al terremoto.",
  ui_story_5015_50150601_244_dialog_content = "¿Quieres escucharlo ahora?",
  ui_story_5015_50150601_245_dialog_content = "¡Por supuesto!",
  ui_story_5015_50150601_246_dialog_content = "El mayordomo dijo que lamenta no poder seguir acompañándote.",
  ui_story_5015_50150601_247_dialog_content = "Y quería que te transmitiera sus disculpas.",
  ui_story_5015_50150601_248_dialog_content = "... Esta bien, lo tengo.",
  ui_story_5015_50150601_249_dialog_content = "Oh, Gretel, ¿por qué tienes los ojos rojos? ¿Hay arena...?",
  ui_story_5015_50150601_250_dialog_content = "Ruby, déjate de bromas pesadas ahora mismo.",
  ui_story_5015_50150601_251_dialog_content = "Ah... lo siento.",
  ui_story_5015_50150601_252_dialog_content = "Valencia, Gretel, este es mi comunicador... Agárrense.",
  ui_story_5015_50150601_253_dialog_content = "No es necesario que me des uno. Tengo el comunicador de mi padre, para poder comunicarme contigo.",
  ui_story_5015_50150601_254_dialog_content = "Lo sé, pero todavía quiero que tomes el mío. Es más seguro tener uno más.",
  ui_story_5015_50150601_255_dialog_content = "Además, si tienes esto, puedes mantener a salvo la reliquia de tu padre...",
  ui_story_5015_50150601_256_dialog_content = "Solo usa el comunicador que te di si quieres contactar a alguien en el futuro.",
  ui_story_5015_50150601_257_dialog_content = "Además, quiero llevarme el diario de tu padre a Illumina. ¿Podrías...",
  ui_story_5015_50150601_258_dialog_content = "Oh, sí, puedes tomarlo... Gracias.",
  ui_story_5015_50150601_259_dialog_content = "... Estoy de acuerdo con mi hermana ...",
  ui_story_5015_50150601_260_dialog_content = "Vale, si alguna vez quieres volver, házmelo saber.",
  ui_story_5015_50150601_261_dialog_content = "Illumina siempre te recibirá con los brazos abiertos.",
  ui_story_5015_50150601_262_dialog_content = "Lo mismo ocurre con la Iglesia de la Lumopolis.",
  ui_story_5015_50150601_263_dialog_content = "Todos, ¿necesitan que los lleve con el Coloso?",
  ui_story_5015_50150601_264_dialog_content = "Primero iremos a Lumopolis y Umbraton, luego a Illumina... También podemos volar al desierto de Rediesel.",
  ui_story_5015_50150601_265_dialog_content = "¡Estupendo! Rouge, Valencia, Gretel, vamos a dar una vuelta por PlayerName¡Es Coloso ahora!",
  ui_story_5015_50150601_266_dialog_content = "¿Coloso? ¿Es el coloso del que habló el mayordomo?",
  ui_story_5015_50150601_267_dialog_content = "¿Quieres saber? ¡Sólo sígueme!",
  ui_story_5015_50150601_268_dialog_content = "¡Señorita Siobhan, vámonos!",
  ui_story_5015_50150601_269_dialog_content = "Luego iré contigo... Todavía quiero charlar con Valencia y los demás en el camino.",
  ui_story_5015_50150601_270_dialog_content = "Florine, Erica, ¿y vosotros?",
  ui_story_5015_50150601_271_dialog_content = "Con mucho gusto aceptamos su invitación, Princesa Carleen.",
  ui_story_5015_50150601_272_dialog_content = "Vamos pues... Empezaremos una nueva aventura con Valencia y Gretel.",
  ui_story_5015_50150601_273_dialog_content = "Recibí un conjunto de señales misteriosas y descubrí accidentalmente las ruinas antiguas...",
  ui_story_5015_50150601_274_dialog_content = "... Tras la verificación, la señal misteriosa fue enviada por el investigador desaparecido de Illumina, Seamus, antes de su muerte...",
  ui_story_5015_50150601_275_dialog_content = "... Las ruinas se encuentran bajo tierra. Parece una ciudad de refugio civil...",
  ui_story_5015_50150601_276_dialog_content = "... Las ruinas ya no tienen residentes. Se desconoce el motivo de su desaparición. Especulo que la razón de esto es una invasión de Eclipsite...",
  ui_story_5015_50150601_277_dialog_content = "... Los hijos de Seamus, Valencia y Gretel, vivían bajo el cuidado de una inteligencia artificial llamada Butler...",
  ui_story_5015_50150601_278_dialog_content = "... He obtenido todos los datos de investigación dejados por Seamus. Esto será de gran beneficio para futuras investigaciones...",
  ui_story_5015_50150601_279_dialog_content = "... Como no había suficiente tiempo, no pude obtener información sobre la inteligencia artificial...",
  ui_story_5015_50150601_280_dialog_content = "... Tampoco pude salvar las estrellas de Alquimia, la fuente de poder que estaba al borde de la destrucción...",
  ui_story_5015_50150601_281_dialog_content = "... Decidiremos si excavar las ruinas después de estudiar los datos de Seamus...",
  ui_story_5015_50150601_282_dialog_content = "... Seamus sirvió a Illumina con todo su corazón y alma...",
  ui_story_5015_50150601_283_dialog_content = "... Incluso en una situación desesperada, no se dio por vencido en encontrar un camino de supervivencia para la generación futura...",
  ui_story_5015_50150601_284_dialog_content = "... Sus acciones en las ruinas mostraron el noble espíritu de Illumina. Es un ejemplo para todos nosotros...",
  ui_story_5015_50150601_285_dialog_content = "... Eso es todo por mi informe.",
  ui_story_5015_50150601_286_dialog_content = "... Esplendor Ilumina!",
  ui_story_5015_50150601_287_dialog_content = "... Nimbus reconstruyó su fe en el Dios de la Luz y reflexionó profundamente...",
  ui_story_5015_50150601_288_dialog_content = "... En los documentos escritos que dejó, Nimbus confió a sus dos hijas a la iglesia...",
  ui_story_5015_50150601_289_dialog_content = "... Creo que, por la bondad del Dios de la Luz, la iglesia debería albergar a las dos niñas...",
  ui_story_5015_50150601_290_dialog_content = "... Muchas de las inteligencias artificiales en las ruinas ya han dejado de funcionar...",
  ui_story_5015_50150601_291_dialog_content = "... La inteligencia artificial responsable del módulo biológico modificó muchos Eclipsites y fue nuestro enemigo más peligroso en las ruinas...",
  ui_story_5015_50150601_292_dialog_content = "... La amonestación del Dios de la Luz ha sido comprobada...",
  ui_story_5015_50150601_293_dialog_content = "... La inteligencia artificial de las ruinas y la fuente de energía, las estrellas Alchemy, han sido destruidas por las explosiones...",
  ui_story_5015_50150601_294_dialog_content = "... Aunque la investigadora de Illumina, Siobhan, se llevó los datos de investigación de Seamus...",
  ui_story_5015_50150601_295_dialog_content = "... Seamus nunca se acercó al secreto más siniestro en el corazón de las ruinas...",
  ui_story_5015_50150601_296_dialog_content = "... Esta antigua amenaza ahora ha sido enterrada bajo el polvo y las rocas para siempre...",
  ui_story_5015_50150601_297_dialog_content = "... Eso es todo por ahora.",
  ui_story_5015_50150601_298_dialog_content = "... Noche Blanca en lo alto.",
  ui_story_5015_50150601_299_dialog_content = "Soroz, me pregunto si puedes darme una respuesta si todavía puedes escucharme.",
  ui_story_5015_50150601_300_dialog_content = "¿Es realmente imposible que la inteligencia artificial desarrolle sentimientos?",
  ui_story_5015_50150601_301_dialog_content = "Hace poco conocí una inteligencia artificial que puede comunicarse conmigo a través de una conexión telepática, como tú.",
  ui_story_5015_50150601_302_dialog_content = "Era el guardián de una antigua ciudad subterránea.",
  ui_story_5015_50150601_303_dialog_content = "Al final, optó por sacrificarse para dejarnos escapar, pero no parecía entender los sentimientos.",
  ui_story_5015_50150601_304_dialog_content = "Pensaba que todas sus acciones estaban predeterminadas por su programa.",
  ui_story_5015_50150601_305_dialog_content = "Pero yo no creo eso.",
  ui_story_5015_50150601_306_dialog_content = "Todo ese cuidado, confianza y consuelo durante el tiempo que pasaron juntos... ¿podría ser todo debido a la configuración?",
  ui_story_5015_50150601_307_dialog_content = "Incluso estaba dispuesto a sacrificarse para salvar a otros... ¿Realmente hizo eso para completar su misión?",
  ui_story_5015_50150601_308_dialog_content = "Si esos no son ejemplos de sentimientos, ¿qué son los sentimientos?",
  ui_story_5015_50150601_309_dialog_content = "Si niego todo esto, ¿cómo vivía antes de cumplir los diecisiete años?",
  ui_story_5015_50150601_310_dialog_content = "... Tuvimos mucha suerte de poder escapar de Entrañas con todos nuestros compañeros y esas dos hermanas.",
  ui_story_5015_50150601_311_dialog_content = "Además del mayordomo, también debo agradecer a los padres de esas dos hermanas.",
  ui_story_5015_50150601_312_dialog_content = "No me imagino el precio que pagaron para que sus hijas sobrevivieran...",
  ui_story_5015_50150601_313_dialog_content = "Soroz, seguramente mis padres también hicieron todo lo posible para que yo sobreviviera, ¿no?",
  ui_story_5015_50150601_314_dialog_content = "...",
  ui_story_5015_50150601_315_dialog_content = "¿Cuándo podré volver a escuchar sus respuestas?"
}
return config
